window.CURSO_DEFI = [{"id":"portrait","nivel":"A2.1","tema":"identidade e encontros","titulo":"Un portrait en mouvement","documentoTitulo":"Le message de Lina","documento":"Salut ! Je m'appelle Lina. Je vis à Lyon depuis deux ans, mais je viens de Recife. Je travaille dans une librairie et, le week-end, je fais du théâtre. Je viens de commencer un atelier d'improvisation parce que j'aimerais parler avec plus d'assurance. En ce moment, je cherche aussi des personnes pour pratiquer le français autour d'un café.","ferramentaTitulo":"depuis · venir de · aimerais","ferramenta":"Depuis indique une action qui continue. Venir de + infinitif exprime le passé récent. J'aimerais permet de présenter un souhait avec politesse.","atividades":[{"tipo":"repérage","pergunta":"Pourquoi Lina fait-elle de l'improvisation ?","opcoes":["Pour changer de travail","Pour parler avec plus d'assurance","Pour apprendre à écrire"],"correta":1,"explicacao":"Elle veut gagner de l'assurance quand elle parle."},{"tipo":"grammaire","pergunta":"Complète : Lina habite à Lyon ___ deux ans.","respostas":["depuis"],"resposta":"depuis","explicacao":"L'action a commencé il y a deux ans et continue aujourd'hui."},{"tipo":"reformulation","pergunta":"Dis que Lina a commencé l'atelier il y a très peu de temps.","respostas":["Lina vient de commencer l'atelier","Elle vient de commencer l'atelier"],"resposta":"Lina vient de commencer l'atelier.","explicacao":"Venir de + infinitif = passé récent."},{"tipo":"médiation","pergunta":"Un nouveau membre ne comprend pas le message de Lina.","instrucao":"Explique en français simple qui elle est et ce qu'elle cherche, sans recopier le document.","modelo":"Lina est Brésilienne et vit à Lyon. Elle travaille avec les livres, fait du théâtre et cherche des personnes pour pratiquer le français.","checklist":["les informations essentielles","des phrases plus simples","aucune copie complète"]},{"tipo":"interaction","pergunta":"Prépare trois questions pour faire connaissance avec Lina.","instrucao":"Pose une question sur son parcours, une sur ses goûts et une sur son projet.","modelo":"Depuis quand travailles-tu dans cette librairie ? Quel type de théâtre préfères-tu ? Qu'aimerais-tu améliorer en français ?","checklist":["trois questions","trois thèmes différents","une question avec depuis"]},{"tipo":"écoute à trous","pergunta":"Écoute et complète : « Je vis à Lyon depuis ___. »","audio":"Je vis à Lyon depuis deux ans.","respostas":["deux ans"],"resposta":"deux ans","explicacao":"Depuis accompagne une durée qui continue.","instrucao":"Ouça e escreva somente as palavras que faltam."},{"tipo":"associations","pergunta":"Relie chaque intention à sa structure.","pares":[["durée actuelle","depuis"],["passé récent","venir de"],["souhait poli","j'aimerais"]]},{"tipo":"traduction","pergunta":"Traduza: Eu gostaria de praticar francês.","respostas":["J'aimerais pratiquer le français","Je voudrais pratiquer le français"],"resposta":"J'aimerais pratiquer le français.","explicacao":"J'aimerais e je voudrais expressam um desejo de forma polida."},{"tipo":"mission","pergunta":"Présente-toi à un groupe d'échange linguistique.","instrucao":"Écris 3 ou 4 phrases avec depuis, une activité et un souhait.","modelo":"Je vis à São Paulo depuis trois ans. J'étudie le français et je fais de la danse. J'aimerais rencontrer des francophones pour pratiquer.","checklist":["une durée avec depuis","une activité","un souhait avec j'aimerais"]},{"tipo":"lecture guidée","pergunta":"Samir écrit : « Je suis infirmier à Nantes depuis six mois. Le mardi, je retrouve un groupe de conversation. Je voudrais mieux comprendre mes collègues. » Pourquoi participe-t-il au groupe ?","opcoes":["Pour changer de profession","Pour mieux comprendre ses collègues","Pour quitter Nantes"],"correta":1,"explicacao":"Son objectif est de mieux comprendre ses collègues ; son métier est déjà infirmier."},{"tipo":"grammaire","pergunta":"Complète : Nous ___ de terminer notre premier cours. (venir)","respostas":["venons"],"resposta":"venons","explicacao":"Nous venons de + infinitif : une action très récente."},{"tipo":"remettre en ordre","pergunta":"Remets dans l'ordre : depuis / ici / elle / janvier / travaille.","respostas":["Elle travaille ici depuis janvier","Depuis janvier elle travaille ici"],"resposta":"Elle travaille ici depuis janvier.","explicacao":"Depuis peut introduire une date de début, pas seulement une durée."},{"tipo":"écoute à trous","pergunta":"Écoute et complète : « Je travaille dans un café ___. »","audio":"Je travaille dans un café depuis septembre.","respostas":["depuis septembre"],"resposta":"depuis septembre","explicacao":"Dans un café indique le lieu ; depuis septembre indique le début.","instrucao":"Ouça e escreva somente as palavras que faltam."},{"tipo":"écoute ciblée","pergunta":"Écoute le message. Quand aura lieu la rencontre ?","audio":"Salut, notre rencontre était prévue mardi. Finalement, on se retrouve jeudi à dix-neuf heures devant la bibliothèque.","opcoes":["Mardi à dix-neuf heures","Jeudi à neuf heures","Jeudi à dix-neuf heures"],"correta":2,"explicacao":"Finalement annonce le changement : jeudi à dix-neuf heures.","instrucao":"Ouça quantas vezes precisar e responda sobre o que foi dito."},{"tipo":"traduction","pergunta":"Traduza: Acabamos de chegar a Nantes.","respostas":["Nous venons d'arriver à Nantes","On vient d'arriver à Nantes"],"resposta":"Nous venons d'arriver à Nantes.","explicacao":"Venir de devient venir d' devant une voyelle."},{"tipo":"corriger","pergunta":"Corrige le verbe : « Je habite ici depuis deux ans. »","respostas":["J'habite ici depuis deux ans"],"resposta":"J'habite ici depuis deux ans.","explicacao":"Je s'élide devant habite : j'habite."},{"tipo":"associations","pergunta":"Relie chaque question à la réponse qui convient.","pares":[["Depuis quand habites-tu ici ?","Depuis mars."],["D'où viens-tu ?","Je viens de Recife."],["Qu'aimerais-tu faire ?","J'aimerais parler davantage."],["Qu'est-ce que tu viens de faire ?","Je viens de finir un livre."]]},{"tipo":"carnet d'écriture","pergunta":"Écris un message pour rejoindre un échange linguistique.","instrucao":"Écris 35 à 55 mots : présente ton activité, depuis quand tu apprends et ce que tu aimerais pratiquer. Compare ensuite avec le modèle.","minPalavras":35,"modelo":"Bonjour ! Je m'appelle Ana et je travaille dans une école. J'apprends le français depuis huit mois. Je viens de découvrir votre groupe et j'aimerais participer samedi. Je voudrais surtout mieux comprendre les conversations et parler de mes voyages. Est-ce qu'il reste une place ?","checklist":["J'ai présenté mon activité.","J'ai utilisé depuis avec une durée.","J'ai formulé un souhait et une question."]},{"tipo":"atelier oral","oral":true,"pergunta":"Présente-toi à voix haute pendant 45 secondes.","instrucao":"Écoute le modèle, puis parle de toi sans le lire. Recommence une fois. Coche seulement ce que tu as réellement fait ; c'est une autoévaluation.","audio":"Bonjour, je m'appelle Inès. J'habite ici depuis un an. Je viens de commencer un nouveau travail. J'aimerais rencontrer des personnes pour parler français.","modelo":"Bonjour, je m'appelle Inès. J'habite ici depuis un an. Je viens de commencer un nouveau travail. J'aimerais rencontrer des personnes pour parler français.","checklist":["J'ai dit qui je suis et ce que je fais.","J'ai utilisé depuis et j'aimerais.","J'ai parlé une deuxième fois sans lire."]}]},{"id":"quartier","nivel":"A2.1","tema":"ville et logement","titulo":"Mon quartier idéal","documentoTitulo":"Deux avis sur Belle-Rive","documento":"Noé adore Belle-Rive : le quartier est plus calme que le centre et il y a beaucoup d'espaces verts. Maya est moins enthousiaste. Pour elle, les bus ne sont pas assez fréquents et les commerces sont trop loin. Tous les deux apprécient pourtant le marché du dimanche, où les habitants se retrouvent.","ferramentaTitulo":"plus… que · moins… que · assez · trop","ferramenta":"Plus/moins + adjectif + que sert à comparer. Assez exprime une quantité suffisante; trop indique un excès.","atividades":[{"tipo":"compréhension","pergunta":"Sur quel point Noé et Maya sont-ils d'accord ?","opcoes":["Les transports","Le marché","La distance des commerces"],"correta":1,"explicacao":"Tous les deux apprécient le marché du dimanche."},{"tipo":"lexique","pergunta":"Complète : Les bus ne sont pas ___ fréquents.","respostas":["assez"],"resposta":"assez","explicacao":"Ils ne passent pas suffisamment souvent."},{"tipo":"grammaire","pergunta":"Compare Belle-Rive et le centre avec calme.","respostas":["Belle-Rive est plus calme que le centre","Le quartier est plus calme que le centre"],"resposta":"Belle-Rive est plus calme que le centre.","explicacao":"Plus + adjectif + que construit le comparatif de supériorité."},{"tipo":"médiation","pergunta":"Résume les deux opinions pour une personne qui veut déménager.","instrucao":"Présente un point positif, deux limites et un point commun.","modelo":"Belle-Rive est calme et vert. Cependant, les bus sont peu fréquents et les commerces sont loin. Noé et Maya aiment tous les deux le marché.","checklist":["un avantage","deux limites","l'accord sur le marché"]},{"tipo":"interaction","pergunta":"Prépare une question pour chaque besoin.","instrucao":"Une famille cherche des écoles; une étudiante pense aux transports; un retraité veut du calme.","modelo":"Est-ce qu'il y a de bonnes écoles ? Les bus passent-ils souvent ? Le quartier est-il bruyant le soir ?","checklist":["trois questions","un besoin par question","vocabulaire du quartier"]},{"tipo":"écoute à trous","pergunta":"Écoute et complète : « Le quartier est plus calme que ___. »","audio":"Le quartier est plus calme que le centre.","respostas":["le centre"],"resposta":"le centre","explicacao":"Plus calme que forme une comparaison.","instrucao":"Ouça e escreva somente as palavras que faltam."},{"tipo":"associations","pergunta":"Relie les mots à leur idée.","pares":[["assez","quantité suffisante"],["trop","quantité excessive"],["moins que","comparaison inférieure"]]},{"tipo":"traduction","pergunta":"Traduza: Os ônibus não são frequentes o suficiente.","respostas":["Les bus ne sont pas assez fréquents"],"resposta":"Les bus ne sont pas assez fréquents.","explicacao":"Pas assez indica insuficiência."},{"tipo":"mission","pergunta":"Recommande un quartier à une amie.","instrucao":"Présente deux avantages, un inconvénient et une comparaison.","modelo":"Je te conseille Vila Mariana. Le quartier est plus tranquille que le centre et les transports sont pratiques. En revanche, les loyers sont un peu trop chers.","checklist":["deux avantages","un inconvénient","une comparaison"]},{"tipo":"lecture guidée","pergunta":"Annonce : « Studio près du tram, sans ascenseur, au quatrième étage. Marché à cinq minutes à pied. Rue animée le soir. » Quel inconvénient est certain ?","opcoes":["Il faut monter les escaliers","Le marché est trop loin","Il n'y a pas de tram"],"correta":0,"explicacao":"Sans ascenseur au quatrième étage implique de monter les escaliers."},{"tipo":"grammaire","pergunta":"Complète : Cette rue est ___ bruyante que la grande avenue. On y entend moins de voitures.","respostas":["moins"],"resposta":"moins","explicacao":"La deuxième phrase indique une diminution : moins bruyante que."},{"tipo":"remettre en ordre","pergunta":"Remets dans l'ordre : est / appartement / assez / cet / lumineux.","respostas":["Cet appartement est assez lumineux"],"resposta":"Cet appartement est assez lumineux.","explicacao":"Assez se place devant l'adjectif lumineux."},{"tipo":"écoute à trous","pergunta":"Écoute et complète : « Le marché est plus proche que ___. »","audio":"Le marché est plus proche que la gare.","respostas":["la gare"],"resposta":"la gare","explicacao":"Plus proche que compare deux distances.","instrucao":"Ouça e escreva somente as palavras que faltam."},{"tipo":"écoute ciblée","pergunta":"Écoute l'itinéraire. Où faut-il tourner ?","audio":"Sortez de la station, marchez tout droit jusqu'à la pharmacie, puis tournez à gauche. La médiathèque est en face du parc.","opcoes":["À droite avant la station","À gauche à la pharmacie","À gauche après le parc"],"correta":1,"explicacao":"L'instruction est de tourner à gauche une fois arrivé à la pharmacie.","instrucao":"Ouça quantas vezes precisar e responda sobre o que foi dito."},{"tipo":"traduction","pergunta":"Traduza: Este apartamento é caro demais para mim.","respostas":["Cet appartement est trop cher pour moi"],"resposta":"Cet appartement est trop cher pour moi.","explicacao":"Trop indique un excès ; assez indique que la quantité suffit."},{"tipo":"corriger","pergunta":"Corrige la comparaison : « Ce quartier est plus calme de mon ancien quartier. »","respostas":["Ce quartier est plus calme que mon ancien quartier"],"resposta":"Ce quartier est plus calme que mon ancien quartier.","explicacao":"Le deuxième élément d'une comparaison est introduit par que."},{"tipo":"associations","pergunta":"Relie le problème à la demande adaptée.","pares":[["Le loyer dépasse mon budget.","Avez-vous un logement moins cher ?"],["Je travaille de nuit.","La rue est-elle calme la journée ?"],["Je n'ai pas de voiture.","Y a-t-il un arrêt de bus près d'ici ?"],["Je monte difficilement les escaliers.","L'immeuble a-t-il un ascenseur ?"]]},{"tipo":"carnet d'écriture","pergunta":"Compare deux logements pour un ami.","instrucao":"Écris 40 à 60 mots. A : 650 euros, petit, près du tram. B : 580 euros, grand, loin du centre. Compare au moins deux critères et conseille un logement.","minPalavras":40,"modelo":"Le logement A est plus cher que le logement B, mais il est près du tram. Le B est plus grand et moins cher. Cependant, il est loin du centre. Comme tu travailles en ville et que tu n'as pas de voiture, je te conseille le A.","checklist":["J'ai comparé le prix et un autre critère.","J'ai utilisé plus ou moins avec que.","J'ai expliqué mon conseil."]},{"tipo":"atelier oral","oral":true,"pergunta":"Demande des renseignements sur un logement.","instrucao":"Joue les deux rôles pendant une minute : pose trois questions, invente des réponses, puis explique ton choix. Écoute d'abord l'exemple.","audio":"Bonjour, je vous appelle pour le studio. Est-ce qu'il est près du tram ? Le loyer comprend-il les charges ? Est-ce que je peux le visiter samedi ?","modelo":"Bonjour, je vous appelle pour le studio. Est-ce qu'il est près du tram ? Le loyer comprend-il les charges ? Est-ce que je peux le visiter samedi ?","checklist":["J'ai posé trois questions à voix haute.","J'ai répondu en phrases complètes.","J'ai justifié mon choix avec parce que."]}]},{"id":"consommer","nivel":"A2.1","tema":"consommation responsable","titulo":"Acheter autrement","documentoTitulo":"Le défi de Sami","documento":"Ce mois-ci, Sami n'achète aucun vêtement neuf. Il en trouve dans des friperies ou il échange ceux qu'il ne porte plus. Il répare aussi ses appareils avant de les remplacer. Au début, ses amis trouvaient cette idée compliquée; maintenant, plusieurs d'entre eux veulent essayer.","ferramentaTitulo":"en · aucun · ne… plus","ferramenta":"En remplace un groupe introduit par de ou une quantité. Aucun et ne… plus construisent des négations précises.","atividades":[{"tipo":"compréhension","pergunta":"Que fait Sami avec les vêtements qu'il ne porte plus ?","opcoes":["Il les jette","Il les échange","Il les vend toujours"],"correta":1,"explicacao":"Le document dit qu'il échange les vêtements qu'il ne porte plus."},{"tipo":"grammaire","pergunta":"Réponds avec en : Tu achètes des vêtements neufs ? — Non, …","respostas":["je n'en achète pas","non je n'en achète pas"],"resposta":"Non, je n'en achète pas.","explicacao":"En remplace des vêtements neufs."},{"tipo":"transformation","pergunta":"Mets à la forme négative : Il achète encore des appareils neufs.","respostas":["Il n'achète plus d'appareils neufs"],"resposta":"Il n'achète plus d'appareils neufs.","explicacao":"Ne… plus signifie que l'action a cessé."},{"tipo":"médiation","pergunta":"Explique le défi de Sami à un ami pressé.","instrucao":"Résume en deux phrases ce qu'il refuse et les solutions qu'il choisit.","modelo":"Sami refuse d'acheter des vêtements neufs ce mois-ci. Il choisit les friperies, l'échange et la réparation.","checklist":["le refus","au moins deux solutions","deux phrases maximum"]},{"tipo":"interaction","pergunta":"Réponds à une objection.","instrucao":"Ton ami dit : « Acheter d'occasion, c'est trop compliqué. » Réponds avec un exemple concret.","modelo":"Je comprends, mais on peut commencer par une seule chose. Par exemple, tu peux chercher un manteau dans une friperie près de chez toi.","checklist":["reconnaître l'objection","proposer une petite action","donner un exemple"]},{"tipo":"écoute à trous","pergunta":"Écoute et complète : « Je n'achète aucun ___. »","audio":"Je n'achète aucun vêtement neuf.","respostas":["vêtement neuf"],"resposta":"vêtement neuf","explicacao":"Aucun reforça a ausência total.","instrucao":"Ouça e escreva somente as palavras que faltam."},{"tipo":"associations","pergunta":"Relie l'action à la solution responsable.","pares":[["un pull abîmé","le réparer"],["un objet inutile","l'échanger"],["un manteau recherché","la friperie"]]},{"tipo":"traduction","pergunta":"Traduza: Eu não compro mais aparelhos novos.","respostas":["Je n'achète plus d'appareils neufs"],"resposta":"Je n'achète plus d'appareils neufs.","explicacao":"Ne… plus indica que a ação parou."},{"tipo":"mission","pergunta":"Propose un mini-défi responsable.","instrucao":"Explique ce que tu vas éviter, remplacer et réutiliser pendant une semaine.","modelo":"Pendant une semaine, je n'achèterai aucune bouteille en plastique. Je la remplacerai par une gourde et je réutiliserai mes sacs.","checklist":["une durée","une négation","trois actions concrètes"]},{"tipo":"lecture guidée","pergunta":"Une boutique écrit : « Apportez vos bocaux propres. Nous pesons le récipient vide avant de le remplir. Vous payez uniquement le produit. » Que paie le client ?","opcoes":["Le poids du bocal et du produit","Seulement le produit","Un nouveau bocal obligatoire"],"correta":1,"explicacao":"Le récipient est pesé séparément ; son poids n'est pas facturé."},{"tipo":"grammaire","pergunta":"Réponds avec en : Tu achètes trois pommes ? — Oui, ___.","respostas":["j'en achète trois"],"resposta":"J'en achète trois.","explicacao":"En remplace pommes, mais le nombre trois reste dans la phrase."},{"tipo":"remettre en ordre","pergunta":"Remets dans l'ordre : plus / nous / sacs / de / n'achetons / en plastique.","respostas":["Nous n'achetons plus de sacs en plastique"],"resposta":"Nous n'achetons plus de sacs en plastique.","explicacao":"Ne… plus indique l'arrêt d'une habitude ; des devient de après la négation."},{"tipo":"écoute à trous","pergunta":"Écoute et complète : « J'en voudrais deux cents grammes, s'il ___. »","audio":"J'en voudrais deux cents grammes, s'il vous plaît.","respostas":["vous plaît"],"resposta":"vous plaît","explicacao":"En reprend le produit ; deux cents prend un s ici.","instrucao":"Ouça e escreva somente as palavras que faltam."},{"tipo":"écoute ciblée","pergunta":"Écoute. Pourquoi la cliente ne prend-elle pas le pain ?","audio":"Bonjour, je vais prendre des tomates et du riz. Vous avez encore du pain complet ? Non ? Alors je n'en prends pas aujourd'hui.","opcoes":["Il est trop cher","Elle n'aime plus le pain","Il n'y a plus de pain complet"],"correta":2,"explicacao":"La cliente renonce au pain après la réponse négative sur sa disponibilité.","instrucao":"Ouça quantas vezes precisar e responda sobre o que foi dito."},{"tipo":"traduction","pergunta":"Traduza: Não compro mais garrafas de plástico.","respostas":["Je n'achète plus de bouteilles en plastique","J'achète plus de bouteilles en plastique"],"resposta":"Je n'achète plus de bouteilles en plastique.","explicacao":"La forme écrite complète est ne… plus. À l'oral informel, ne est souvent omis."},{"tipo":"corriger","pergunta":"Corrige : « Je n'ai aucun sacs. »","respostas":["Je n'ai aucun sac"],"resposta":"Je n'ai aucun sac.","explicacao":"Aucun accompagne ici un nom au singulier : aucun sac."},{"tipo":"associations","pergunta":"Relie le geste à son résultat.","pares":[["Réparer une fermeture","Prolonger la vie d'un vêtement"],["Acheter en vrac","Réduire les emballages"],["Emprunter une perceuse","Éviter un achat occasionnel"],["Comparer le prix au kilo","Comparer des formats différents"]]},{"tipo":"carnet d'écriture","pergunta":"Écris le bilan d'une semaine de consommation.","instrucao":"En 40 à 60 mots, explique une habitude abandonnée, un nouvel achat et une difficulté. Utilise ne… plus et en au moins une fois.","minPalavras":40,"modelo":"Cette semaine, je n'ai plus acheté de bouteilles en plastique. J'ai utilisé ma gourde au travail et dans le train. Pour les légumes, j'en ai acheté au marché. C'était agréable, mais le magasin en vrac était trop loin. La prochaine fois, je préparerai mieux mon trajet.","checklist":["J'ai présenté un changement concret.","J'ai utilisé ne… plus et en.","J'ai mentionné une difficulté sans exagérer le résultat."]},{"tipo":"atelier oral","oral":true,"pergunta":"Joue une commande au marché.","instrucao":"Écoute, puis commande deux produits avec des quantités. Demande le prix et refuse poliment un troisième produit. Rejoue sans lire.","audio":"Bonjour, je voudrais des poires. J'en prends quatre. Vous avez des noix ? J'en voudrais cent grammes. Non merci, je n'ai pas besoin de sac.","modelo":"Bonjour, je voudrais des poires. J'en prends quatre. Vous avez des noix ? J'en voudrais cent grammes. Non merci, je n'ai pas besoin de sac.","checklist":["J'ai annoncé deux quantités clairement.","J'ai utilisé en pour reprendre un produit.","J'ai formulé une demande et un refus polis."]}]},{"id":"souvenirs","nivel":"A2.2","tema":"récits et souvenirs","titulo":"Une journée inattendue","documentoTitulo":"Le train arrêté","documento":"Hier, je rentrais chez moi quand le train s'est arrêté en pleine campagne. Il pleuvait et personne ne comprenait la situation. Une voyageuse a sorti un jeu de cartes et nous avons commencé à jouer. Quand le train est reparti, une heure plus tard, tout le wagon riait ensemble.","ferramentaTitulo":"imparfait ou passé composé ?","ferramenta":"L'imparfait installe le décor ou une action en cours. Le passé composé raconte les événements qui font avancer l'histoire.","atividades":[{"tipo":"repérage","pergunta":"Quel événement change l'ambiance dans le wagon ?","opcoes":["La pluie commence","Une voyageuse propose un jeu","Le contrôleur arrive"],"correta":1,"explicacao":"Le jeu crée un moment collectif et détend les voyageurs."},{"tipo":"grammaire","pergunta":"Complète : Il ___ quand le train s'est arrêté. (pleuvoir)","respostas":["pleuvait","il pleuvait"],"resposta":"pleuvait","explicacao":"La pluie constitue le décor : imparfait."},{"tipo":"grammaire","pergunta":"Complète : Soudain, une voyageuse ___ un jeu. (sortir)","respostas":["a sorti","elle a sorti"],"resposta":"a sorti","explicacao":"C'est un événement ponctuel : passé composé."},{"tipo":"médiation","pergunta":"Raconte l'incident à quelqu'un qui n'était pas dans le train.","instrucao":"Résume le décor, l'incident et le changement d'ambiance en trois phrases.","modelo":"Il pleuvait et le train s'est arrêté dans la campagne. Une voyageuse a proposé un jeu de cartes. À la fin, tous les passagers riaient ensemble.","checklist":["le décor","l'événement principal","le résultat"]},{"tipo":"atelier oral","pergunta":"Transforme le récit en message vocal.","instrucao":"Écris les notes de ton message : une introduction, deux événements et une réaction personnelle.","modelo":"Tu ne vas pas croire ce qui m'est arrivé ! Le train s'est arrêté, puis une dame a sorti des cartes. Finalement, j'ai adoré ce moment inattendu.","checklist":["une accroche orale","deux événements","une émotion"]},{"tipo":"écoute à trous","pergunta":"Écoute et complète : « Il pleuvait quand le train ___. »","audio":"Il pleuvait quand le train s'est arrêté.","respostas":["s'est arrêté"],"resposta":"s'est arrêté","explicacao":"Imparfait para o cenário; passé composé para o evento.","instrucao":"Ouça e escreva somente as palavras que faltam."},{"tipo":"associations","pergunta":"Relie chaque élément au bon temps.","pares":[["le décor","imparfait"],["l'événement","passé composé"],["soudain","rupture du récit"]]},{"tipo":"traduction","pergunta":"Traduza: Nós começamos a jogar.","respostas":["Nous avons commencé à jouer","On a commencé à jouer"],"resposta":"Nous avons commencé à jouer.","explicacao":"Começar é um evento concluído: passé composé."},{"tipo":"mission","pergunta":"Raconte un petit imprévu qui finit bien.","instrucao":"Écris 4 phrases : décor, problème, réaction, résultat.","modelo":"Je marchais vers le travail quand mon vélo est tombé en panne. Un voisin s'est arrêté pour m'aider. Nous avons réparé la chaîne et je suis arrivé à l'heure.","checklist":["imparfait pour le décor","passé composé pour les événements","un connecteur temporel"]},{"tipo":"lecture guidée","pergunta":"« Il pleuvait et le bus était en retard. Pendant que Zoé attendait, un ancien camarade l'a reconnue. Ils ont décidé de prendre un café. » Quel événement change la situation ?","opcoes":["La pluie commence","Un camarade reconnaît Zoé","Zoé rate son café"],"correta":1,"explicacao":"Le passé composé présente ici l'événement : un camarade l'a reconnue."},{"tipo":"grammaire","pergunta":"Complète à l'imparfait : Quand j'étais enfant, nous ___ souvent le train. (prendre)","respostas":["prenions"],"resposta":"prenions","explicacao":"Une habitude passée : nous prenions, formé sur pren- avec la terminaison -ions."},{"tipo":"remettre en ordre","pergunta":"Remets dans l'ordre : est / quand / je / le téléphone / lisais / tombé.","respostas":["Je lisais quand le téléphone est tombé","Quand je lisais le téléphone est tombé"],"resposta":"Je lisais quand le téléphone est tombé.","explicacao":"L'imparfait installe l'action en cours ; le passé composé présente l'événement."},{"tipo":"écoute à trous","pergunta":"Écoute et complète : « Nous marchions dans la rue quand nous avons entendu de ___. »","audio":"Nous marchions dans la rue quand nous avons entendu de la musique.","respostas":["la musique"],"resposta":"la musique","explicacao":"Marchions décrit la situation ; avons entendu marque ce qui arrive.","instrucao":"Ouça e escreva somente as palavras que faltam."},{"tipo":"écoute ciblée","pergunta":"Écoute. Qu'a fait le narrateur après avoir trouvé les clés ?","audio":"Je cherchais mes clés partout. Elles étaient dans la poche de mon manteau. Dès que je les ai trouvées, j'ai appelé ma sœur, puis je suis sorti.","opcoes":["Il est sorti immédiatement","Il a appelé sa sœur","Il a acheté un manteau"],"correta":1,"explicacao":"L'ordre est : trouver les clés, appeler sa sœur, sortir.","instrucao":"Ouça quantas vezes precisar e responda sobre o que foi dito."},{"tipo":"traduction","pergunta":"Traduza: Eu estava cozinhando quando você chegou.","respostas":["Je cuisinais quand tu es arrivé","Je cuisinais quand tu es arrivée","Je faisais la cuisine quand tu es arrivé","Je faisais la cuisine quand tu es arrivée"],"resposta":"Je cuisinais quand tu es arrivé(e).","explicacao":"L'accord de arrivé dépend de la personne à qui tu parles."},{"tipo":"corriger","pergunta":"Corrige l'auxiliaire : « Hier, elle a allée au cinéma. »","respostas":["Hier elle est allée au cinéma"],"resposta":"Hier, elle est allée au cinéma.","explicacao":"Aller se conjugue avec être au passé composé : elle est allée."},{"tipo":"associations","pergunta":"Associe le connecteur à son rôle dans un récit.","pares":[["D'abord","Présenter la première étape"],["Pendant que","Présenter deux actions simultanées"],["Soudain","Introduire un événement inattendu"],["Finalement","Présenter l'issue de l'histoire"]]},{"tipo":"carnet d'écriture","pergunta":"Raconte une petite aventure pendant un trajet.","instrucao":"Écris 60 à 80 mots. Installe le lieu et l'ambiance à l'imparfait. Raconte ensuite deux événements au passé composé et termine l'histoire.","minPalavras":60,"modelo":"Samedi, je rentrais chez moi en train. Il faisait froid et les voyageurs étaient fatigués. Soudain, une petite fille a commencé à chanter. Son père a sorti une guitare et plusieurs personnes ont souri. Au début, je regardais par la fenêtre, mais j'ai finalement chanté avec eux. Quand nous sommes arrivés, personne ne voulait quitter le wagon. Ce trajet ordinaire est devenu un très beau souvenir.","checklist":["J'ai décrit le contexte à l'imparfait.","J'ai raconté deux événements au passé composé.","Mon récit a une fin et des connecteurs."]},{"tipo":"atelier oral","oral":true,"pergunta":"Raconte une rencontre inattendue pendant une minute.","instrucao":"Prépare cinq mots-clés seulement. Parle, puis recommence en distinguant mieux le contexte et les événements. Le modèle sert de point de départ.","audio":"Je faisais les courses quand j'ai rencontré mon ancien professeur. Il habitait maintenant dans mon quartier. Nous avons discuté quelques minutes, puis nous avons échangé nos numéros.","modelo":"Je faisais les courses quand j'ai rencontré mon ancien professeur. Il habitait maintenant dans mon quartier. Nous avons discuté quelques minutes, puis nous avons échangé nos numéros.","checklist":["J'ai situé l'histoire dans le passé.","J'ai alterné contexte et événements.","J'ai raconté sans lire de phrases complètes."]}]},{"id":"equilibre","nivel":"A2.2","tema":"bien-être numérique","titulo":"Retrouver son attention","documentoTitulo":"Une soirée sans écran","documento":"Chaque mercredi, Inès éteint son téléphone à 20 heures. Elle conseille à ses proches de faire la même chose. Selon elle, il faut que chacun trouve un moment sans notifications. Depuis qu'elle a adopté cette habitude, elle dort mieux et lit davantage.","ferramentaTitulo":"conseiller de · il faut que","ferramenta":"Conseiller à quelqu'un de + infinitif donne un conseil personnel. Il faut que + subjonctif présente une nécessité générale.","atividades":[{"tipo":"compréhension","pergunta":"Quel changement Inès observe-t-elle ?","opcoes":["Elle travaille plus tard","Elle dort mieux","Elle reçoit plus de messages"],"correta":1,"explicacao":"Elle dort mieux et lit davantage."},{"tipo":"grammaire","pergunta":"Complète : Elle conseille à ses proches ___ éteindre leur téléphone.","respostas":["d'","de","d'éteindre"],"resposta":"d'éteindre","explicacao":"Conseiller à quelqu'un de + infinitif."},{"tipo":"grammaire","pergunta":"Complète : Il faut que tu ___ une pause. (faire)","respostas":["fasses","tu fasses"],"resposta":"fasses","explicacao":"Après il faut que, faire devient fasses au subjonctif."},{"tipo":"médiation","pergunta":"Transmets la méthode d'Inès à un groupe de classe.","instrucao":"Explique la règle, sa fréquence et deux résultats observés.","modelo":"Inès passe une soirée sans téléphone chaque mercredi à partir de 20 heures. Grâce à cette habitude, elle dort mieux et lit plus.","checklist":["la règle","le moment","deux résultats"]},{"tipo":"interaction","pergunta":"Négocie une règle commune pour un dîner.","instrucao":"Fais une proposition, accepte une idée et ajoute une condition.","modelo":"On pourrait laisser les téléphones dans nos sacs. D'accord pour les garder éteints, mais il faut que chacun puisse répondre en cas d'urgence.","checklist":["une proposition","une marque d'accord","une condition"]},{"tipo":"écoute à trous","pergunta":"Écoute et complète : « Il faut que tu fasses ___. »","audio":"Il faut que tu fasses une pause.","respostas":["une pause"],"resposta":"une pause","explicacao":"Faire vira fasses no subjonctif.","instrucao":"Ouça e escreva somente as palavras que faltam."},{"tipo":"associations","pergunta":"Relie le conseil à son degré.","pares":[["Tu pourrais…","suggestion douce"],["Je te conseille de…","conseil direct"],["Il faut que…","nécessité"]]},{"tipo":"traduction","pergunta":"Traduza: Eu te aconselho a desligar o telefone.","respostas":["Je te conseille d'éteindre le téléphone","Je te conseille d'éteindre ton téléphone"],"resposta":"Je te conseille d'éteindre ton téléphone.","explicacao":"Conseiller à quelqu'un de + infinitif."},{"tipo":"mission","pergunta":"Donne trois conseils pour une soirée plus calme.","instrucao":"Utilise tu pourrais, je te conseille de et il faut que.","modelo":"Tu pourrais couper les notifications. Je te conseille de laisser le téléphone dans une autre pièce. Il faut que tu choisisses une activité relaxante.","checklist":["tu pourrais","je te conseille de","il faut que + subjonctif"]},{"tipo":"lecture guidée","pergunta":"« Depuis une semaine, Léo laisse son téléphone dans l'entrée pendant le dîner. Il continue à appeler ses proches après le repas. Il se sent plus disponible. » Quel changement a-t-il fait ?","opcoes":["Il a arrêté tout contact avec ses proches","Il limite le téléphone pendant le repas","Il a supprimé tous ses appels"],"correta":1,"explicacao":"Il change un moment d'utilisation, pas toutes ses habitudes numériques."},{"tipo":"grammaire","pergunta":"Complète : Il faut que tu ___ une pause. (faire)","respostas":["fasses"],"resposta":"fasses","explicacao":"Il faut que demande le subjonctif : que tu fasses."},{"tipo":"remettre en ordre","pergunta":"Remets dans l'ordre : conseille / je / de / notifications / les / te / désactiver.","respostas":["Je te conseille de désactiver les notifications"],"resposta":"Je te conseille de désactiver les notifications.","explicacao":"Conseiller à quelqu'un de faire quelque chose : je te conseille de…"},{"tipo":"écoute à trous","pergunta":"Écoute et complète : « Tu pourrais laisser ton téléphone dans une ___. »","audio":"Tu pourrais laisser ton téléphone dans une autre pièce.","respostas":["autre pièce"],"resposta":"autre pièce","explicacao":"Pourrais permet de proposer sans imposer.","instrucao":"Ouça e escreva somente as palavras que faltam."},{"tipo":"écoute ciblée","pergunta":"Écoute. Quelle solution a réellement aidé la personne ?","audio":"J'avais essayé de supprimer toutes mes applications, mais je les installais à nouveau. Maintenant, je coupe les notifications pendant une heure quand je lis. Cela m'aide vraiment.","opcoes":["Ne plus jamais utiliser d'applications","Acheter un nouveau téléphone","Couper les notifications pendant la lecture"],"correta":2,"explicacao":"Maintenant introduit la solution actuelle, contrairement à la tentative abandonnée.","instrucao":"Ouça quantas vezes precisar e responda sobre o que foi dito."},{"tipo":"traduction","pergunta":"Traduza: Aconselho você a descansar um pouco.","respostas":["Je te conseille de te reposer un peu","Je vous conseille de vous reposer un peu"],"resposta":"Je te conseille de te reposer un peu.","explicacao":"Le pronom de se reposer suit la personne : te reposer ou vous reposer."},{"tipo":"corriger","pergunta":"Corrige : « Il faut que nous faisons une pause. »","respostas":["Il faut que nous fassions une pause"],"resposta":"Il faut que nous fassions une pause.","explicacao":"Après il faut que, on emploie le subjonctif : fassions."},{"tipo":"associations","pergunta":"Relie chaque formulation à son intention.","pares":[["Tu pourrais essayer…","Faire une suggestion douce"],["Il faut que tu…","Exprimer une nécessité"],["Je te conseille de…","Donner un conseil"],["Et si on faisait une pause ?","Proposer une action ensemble"]]},{"tipo":"carnet d'écriture","pergunta":"Réponds à un ami qui n'arrive pas à se concentrer.","instrucao":"Écris 60 à 80 mots : montre que tu comprends, donne deux conseils réalisables et propose un essai limité dans le temps.","minPalavras":60,"modelo":"Je comprends que ce soit difficile quand ton téléphone sonne tout le temps. Tu pourrais commencer par couper les notifications pendant vingt minutes. Je te conseille aussi de préparer une seule tâche avant de travailler. Il faut que tu gardes des pauses : le but n'est pas de tout supprimer. Essaie cette organisation pendant trois jours, puis dis-moi ce qui t'aide vraiment.","checklist":["J'ai montré de la compréhension.","J'ai donné deux conseils différents.","J'ai proposé une durée d'essai précise."]},{"tipo":"atelier oral","oral":true,"pergunta":"Propose une nouvelle habitude à un ami.","instrucao":"Parle pendant une minute. Propose une idée, imagine une objection et adapte ton conseil. Évite de donner uniquement des ordres.","audio":"Tu pourrais commencer par une petite pause sans écran. Si une heure te semble trop longue, essaie dix minutes. Le plus important, c'est de trouver une habitude qui te convient.","modelo":"Tu pourrais commencer par une petite pause sans écran. Si une heure te semble trop longue, essaie dix minutes. Le plus important, c'est de trouver une habitude qui te convient.","checklist":["J'ai utilisé une formulation polie.","J'ai répondu à une objection.","J'ai donné un exemple concret à voix haute."]}]},{"id":"projets","nivel":"A2.2","tema":"études et avenir","titulo":"Changer de cap","documentoTitulo":"Le projet de Mehdi","documento":"Mehdi terminera sa formation en juin. Ensuite, il aimerait travailler dans une entreprise sociale. S'il trouve un poste à Marseille, il déménagera; sinon, il cherchera une mission à distance. Son objectif est d'utiliser ses compétences pour un projet utile.","ferramentaTitulo":"futur · conditionnel · si + présent","ferramenta":"Le futur présente un projet considéré comme probable. Le conditionnel exprime un souhait. Si + présent est suivi du futur pour une condition réalisable.","atividades":[{"tipo":"compréhension","pergunta":"Quel type d'entreprise intéresse Mehdi ?","opcoes":["Une entreprise sociale","Une banque internationale","Un commerce familial"],"correta":0,"explicacao":"Il aimerait travailler dans une entreprise sociale."},{"tipo":"grammaire","pergunta":"Complète : S'il trouve un poste, il ___. (déménager)","respostas":["déménagera","il déménagera"],"resposta":"déménagera","explicacao":"Si + présent, puis futur simple."},{"tipo":"nuance","pergunta":"Exprime un souhait : Je travaille dans une association.","respostas":["J'aimerais travailler dans une association","Je voudrais travailler dans une association"],"resposta":"J'aimerais travailler dans une association.","explicacao":"Le conditionnel rend le projet souhaité, pas encore certain."},{"tipo":"médiation","pergunta":"Présente le projet de Mehdi à une conseillère.","instrucao":"Distingue ce qui est certain, souhaité et conditionnel.","modelo":"Mehdi finira sa formation en juin. Il souhaite rejoindre une entreprise sociale. Il déménagera à Marseille s'il y trouve un poste.","checklist":["un fait futur","un souhait","une condition"]},{"tipo":"interaction","pergunta":"Prépare un mini-entretien d'orientation.","instrucao":"Écris deux questions de la conseillère et deux réponses de Mehdi.","modelo":"— Dans quel domaine aimeriez-vous travailler ? — Dans l'économie sociale. — Que ferez-vous si vous ne trouvez pas à Marseille ? — Je chercherai un poste à distance.","checklist":["deux questions","deux réponses","conditionnel et futur"]},{"tipo":"écoute à trous","pergunta":"Écoute et complète : « S'il trouve un poste, ___. »","audio":"S'il trouve un poste, il déménagera.","respostas":["il déménagera"],"resposta":"il déménagera","explicacao":"Si + présent, futur simple.","instrucao":"Ouça e escreva somente as palavras que faltam."},{"tipo":"associations","pergunta":"Relie la forme à sa fonction.","pares":[["j'aimerais","souhait"],["je travaillerai","projet futur"],["si je trouve","condition possible"]]},{"tipo":"traduction","pergunta":"Traduza: Se eu mantiver esse ritmo, chegarei ao B1.","respostas":["Si je garde ce rythme j'atteindrai le niveau B1","Si je maintiens ce rythme j'atteindrai le niveau B1"],"resposta":"Si je garde ce rythme, j'atteindrai le niveau B1.","explicacao":"A condição usa présent; o resultado usa futur."},{"tipo":"mission","pergunta":"Présente ton prochain objectif en français.","instrucao":"Indique un souhait, une étape future et une condition.","modelo":"J'aimerais atteindre le niveau B1. Je pratiquerai un peu chaque jour. Si je garde ce rythme, je parlerai avec plus de confiance.","checklist":["un souhait au conditionnel","un verbe au futur","si + présent"]},{"tipo":"lecture guidée","pergunta":"« Emma travaille le jour. Elle souhaite suivre une formation le soir, mais doit d'abord vérifier les horaires et le coût. Elle n'a pas encore envoyé son dossier. » À quelle étape est-elle ?","opcoes":["Elle prépare son inscription","Elle a terminé la formation","Elle a déjà envoyé son dossier"],"correta":0,"explicacao":"Elle recueille les informations nécessaires avant de s'inscrire."},{"tipo":"grammaire","pergunta":"Complète au futur : Si j'obtiens une place, je ___ la formation en octobre. (commencer)","respostas":["commencerai"],"resposta":"commencerai","explicacao":"Si + présent peut être suivi du futur : si j'obtiens…, je commencerai…"},{"tipo":"remettre en ordre","pergunta":"Remets dans l'ordre : aimerais / une / je / suivre / formation / soir / le.","respostas":["J'aimerais suivre une formation le soir","Je aimerais suivre une formation le soir"],"resposta":"J'aimerais suivre une formation le soir.","explicacao":"À l'écrit, on fait l'élision : j'aimerais. Le conditionnel présente le souhait."},{"tipo":"écoute à trous","pergunta":"Écoute et complète : « Si j'ai assez de temps, je préparerai mon dossier ce ___. »","audio":"Si j'ai assez de temps, je préparerai mon dossier ce week-end.","respostas":["week-end"],"resposta":"week-end","explicacao":"La condition est au présent ; le projet est au futur.","instrucao":"Ouça e escreva somente as palavras que faltam."},{"tipo":"écoute ciblée","pergunta":"Écoute. Quelle est la prochaine démarche à faire ?","audio":"Votre candidature nous intéresse. Avant l'entretien, merci d'envoyer votre portfolio. Nous vous proposerons ensuite une date de rendez-vous.","opcoes":["Choisir immédiatement une date","Envoyer son portfolio","Se présenter demain au bureau"],"correta":1,"explicacao":"Avant l'entretien, il faut envoyer le portfolio ; la date vient ensuite.","instrucao":"Ouça quantas vezes precisar e responda sobre o que foi dito."},{"tipo":"traduction","pergunta":"Traduza: Se eu tiver tempo, estudarei amanhã.","respostas":["Si j'ai le temps j'étudierai demain","Si j'ai du temps j'étudierai demain","Si j'ai le temps je vais étudier demain"],"resposta":"Si j'ai le temps, j'étudierai demain.","explicacao":"Le français utilise ici le présent après si, même si la condition concerne demain."},{"tipo":"corriger","pergunta":"Corrige : « Si j'aurai une place, je commencerai en octobre. »","respostas":["Si j'ai une place je commencerai en octobre"],"resposta":"Si j'ai une place, je commencerai en octobre.","explicacao":"Dans cette condition, si est suivi du présent, pas du futur."},{"tipo":"associations","pergunta":"Relie chaque étape à son objectif.","pares":[["Lire le programme","Vérifier le contenu des cours"],["Comparer les horaires","Vérifier la compatibilité avec son travail"],["Préparer un portfolio","Montrer ses réalisations"],["Demander un entretien","Échanger avec le responsable"]]},{"tipo":"carnet d'écriture","pergunta":"Demande des informations sur une formation.","instrucao":"Écris un courriel de 60 à 90 mots. Présente ton projet, pose deux questions précises et explique une condition nécessaire à ton inscription.","minPalavras":60,"modelo":"Bonjour, je travaille actuellement dans une boutique et j'aimerais me former au graphisme. Votre programme m'intéresse, mais j'aurais besoin de quelques renseignements. Les cours ont-ils lieu le soir ? Est-il possible de payer en plusieurs fois ? Si les horaires sont compatibles avec mon travail, je déposerai un dossier cette semaine. Merci d'avance pour votre réponse. Je reste disponible pour un entretien.","checklist":["J'ai présenté le projet clairement.","J'ai posé deux questions précises.","J'ai employé si + présent et une formule de politesse."]},{"tipo":"atelier oral","oral":true,"pergunta":"Présente ton projet et un plan alternatif.","instrucao":"Parle pendant 60 à 90 secondes : objectif, première étape, difficulté possible et autre solution. Utilise le futur et j'aimerais.","audio":"J'aimerais suivre une formation cette année. Je préparerai mon dossier en septembre. Si je ne trouve pas de place, je commencerai par un cours du soir et je présenterai une nouvelle candidature.","modelo":"J'aimerais suivre une formation cette année. Je préparerai mon dossier en septembre. Si je ne trouve pas de place, je commencerai par un cours du soir et je présenterai une nouvelle candidature.","checklist":["J'ai annoncé un objectif et une étape.","J'ai formulé une condition avec si.","J'ai expliqué une solution alternative."]}]},{"id":"info","nivel":"B1","tema":"médias et information","titulo":"Avant de partager","documentoTitulo":"Le réflexe de Maëlle","documento":"Maëlle a reçu un message affirmant qu'une nouvelle règle allait entrer en vigueur le lendemain. Au lieu de le partager immédiatement, elle a cherché l'auteur, la date et une deuxième source. Elle a découvert que l'article avait trois ans. Elle explique désormais à ses amis qu'une information très partagée n'est pas forcément fiable.","ferramentaTitulo":"discours rapporté · fiabilité","ferramenta":"Pour rapporter, on utilise dire/expliquer/affirmer que. Les repères peuvent changer : demain devient le lendemain. Une source fiable indique auteur, date et preuves.","atividades":[{"tipo":"compréhension","pergunta":"Quel détail révèle le problème de l'article ?","opcoes":["Il est trop court","Il a trois ans","Il contient une image"],"correta":1,"explicacao":"La date montre que l'information n'est plus actuelle."},{"tipo":"lexique","pergunta":"Quel mot signifie qu'on peut faire confiance à une source ?","respostas":["fiable","une source fiable"],"resposta":"fiable","explicacao":"Fiable = digne de confiance."},{"tipo":"reformulation","pergunta":"Rapporte : « La règle entrera en vigueur demain. » L'article affirme…","respostas":["L'article affirme que la règle entrera en vigueur le lendemain","que la règle entrera en vigueur le lendemain"],"resposta":"L'article affirme que la règle entrera en vigueur le lendemain.","explicacao":"Dans le récit, demain devient le lendemain."},{"tipo":"médiation","pergunta":"Alerte un proche sans diffuser la rumeur.","instrucao":"Explique pourquoi le message est douteux et conseille deux vérifications.","modelo":"Attention, ce message reprend un article vieux de trois ans. Vérifie la date et cherche une autre source avant de le partager.","checklist":["le problème précis","deux vérifications","un conseil clair"]},{"tipo":"interaction","pergunta":"Réponds à : « Tout le monde le partage, donc c'est vrai. »","instrucao":"Exprime ton désaccord avec respect et donne un argument.","modelo":"Je comprends pourquoi tu le penses, mais le nombre de partages ne prouve rien. Une information fiable doit indiquer ses sources.","checklist":["désaccord poli","un argument","critère de fiabilité"]},{"tipo":"écoute à trous","pergunta":"Écoute et complète : « Une information partagée n'est pas ___. »","audio":"Une information partagée n'est pas forcément fiable.","respostas":["forcément fiable"],"resposta":"forcément fiable","explicacao":"Forcément significa necessariamente.","instrucao":"Ouça e escreva somente as palavras que faltam."},{"tipo":"associations","pergunta":"Relie chaque vérification à sa question.","pares":[["auteur","Qui l'a publié ?"],["date","Quand ?"],["source","Quelle preuve ?"]]},{"tipo":"traduction","pergunta":"Traduza: O artigo afirma que a regra mudará.","respostas":["L'article affirme que la règle changera"],"resposta":"L'article affirme que la règle changera.","explicacao":"Affirmer que introduz o discurso relatado."},{"tipo":"mission","pergunta":"Écris une méthode anti-fausse information.","instrucao":"Donne trois vérifications et justifie la plus importante.","modelo":"Je vérifie l'auteur, la date et l'origine des chiffres. La date est essentielle parce qu'une information vraie peut devenir dépassée.","checklist":["trois vérifications","une justification","un connecteur de cause"]},{"tipo":"lecture critique","pergunta":"Un message affirme : « La piscine ferme définitivement ! » Le site municipal annonce seulement des travaux du 3 au 10 juin. Quelle conclusion est justifiée ?","opcoes":["Le message prouve une fermeture définitive","La source municipale annonce une fermeture temporaire","Les deux messages disent exactement la même chose"],"correta":1,"explicacao":"Une période de travaux limitée ne prouve pas une fermeture définitive."},{"tipo":"grammaire","pergunta":"Rapporte au présent : Paul dit : « Je vérifie la date. » → Paul dit ___.","respostas":["qu'il vérifie la date"],"resposta":"qu'il vérifie la date","explicacao":"Le pronom je devient il ; le verbe introducteur au présent n'impose pas de changement de temps."},{"tipo":"remettre en ordre","pergunta":"Remets dans l'ordre : vérifier / il / avant / source / faut / partager / la / de.","respostas":["Il faut vérifier la source avant de partager"],"resposta":"Il faut vérifier la source avant de partager.","explicacao":"Avant de est suivi d'un infinitif : partager."},{"tipo":"écoute à trous","pergunta":"Écoute et complète : « L'article ne précise ni la date ni l'origine de ___. »","audio":"L'article ne précise ni la date ni l'origine de cette image.","respostas":["cette image"],"resposta":"cette image","explicacao":"Ne… ni… ni coordonne ici deux éléments absents.","instrucao":"Ouça e escreva somente as palavras que faltam."},{"tipo":"écoute critique","pergunta":"Écoute le témoignage. Qu'est-ce qui reste incertain ?","audio":"J'ai vu une vidéo qui montrerait la place hier soir. Mais je ne connais pas la personne qui l'a publiée et la vidéo n'affiche aucune date.","opcoes":["La vidéo existe","La date réelle de la scène","La personne a regardé une vidéo"],"correta":1,"explicacao":"Montrerait exprime une réserve ; aucune date ne permet de confirmer quand la scène a été filmée.","instrucao":"Ouça quantas vezes precisar e responda sobre o que foi dito."},{"tipo":"traduction","pergunta":"Traduza: Ela diz que a informação ainda não foi confirmada.","respostas":["Elle dit que l'information n'a pas encore été confirmée","Elle dit que l'information n'est pas encore confirmée"],"resposta":"Elle dit que l'information n'a pas encore été confirmée.","explicacao":"Encore se place ici après pas ; information est féminin, donc confirmée."},{"tipo":"corriger","pergunta":"Corrige le pronom : Nora dit « Je suis prudente. » → Nora dit que je suis prudente.","respostas":["Nora dit qu'elle est prudente"],"resposta":"Nora dit qu'elle est prudente.","explicacao":"On rapporte les paroles de Nora à la troisième personne : elle."},{"tipo":"associations","pergunta":"Relie chaque vérification à la question utile.","pares":[["Source","Qui publie cette information ?"],["Date","Quand a-t-elle été publiée ?"],["Contexte","Que s'est-il passé avant cette scène ?"],["Recoupement","Une autre source indépendante confirme-t-elle ?"]]},{"tipo":"carnet d'écriture","pergunta":"Réponds à une personne qui partage une rumeur sur la piscine.","instrucao":"Écris 80 à 110 mots : reconnais son inquiétude, distingue ce qui est confirmé de ce qui ne l'est pas, cite la source municipale et propose une vérification. Ne l'accuse pas.","minPalavras":80,"modelo":"Je comprends que ce message t'inquiète, surtout si tu vas souvent à la piscine. Cependant, le site municipal annonce des travaux du 3 au 10 juin, et non une fermeture définitive. Le message partagé ne donne ni source ni explication supplémentaire. Il est donc possible qu'il confonde une fermeture temporaire avec une décision permanente. Avant de le transmettre, nous pourrions consulter la dernière annonce de la mairie ou contacter l'accueil. Si une nouvelle information officielle paraît, nous pourrons alors mettre notre message à jour.","checklist":["J'ai distingué faits confirmés et hypothèses.","J'ai mentionné une source identifiable.","J'ai proposé une démarche sans accuser la personne."]},{"tipo":"atelier oral","oral":true,"pergunta":"Explique pourquoi tu hésites à partager une vidéo.","instrucao":"Parle 90 secondes : résume l'affirmation, exprime deux réserves, puis annonce ce que tu vérifierais. Ne lis pas le modèle.","audio":"La vidéo semble récente, mais je ne peux pas confirmer sa date. La personne qui l'a publiée ne cite aucune source. Je préfère chercher une autre version et vérifier le contexte avant de la partager.","modelo":"La vidéo semble récente, mais je ne peux pas confirmer sa date. La personne qui l'a publiée ne cite aucune source. Je préfère chercher une autre version et vérifier le contexte avant de la partager.","checklist":["J'ai résumé l'affirmation sans la présenter comme certaine.","J'ai exprimé deux réserves.","J'ai expliqué une méthode de vérification à voix haute."]}]},{"id":"agir","nivel":"B1","tema":"écologie et débat","titulo":"Agir près de chez soi","documentoTitulo":"La rue des voisins","documento":"Dans une rue de Nantes, des habitants ont remplacé six places de stationnement par des bancs et des plantes. Certains commerçants craignaient une baisse de fréquentation; pourtant, après trois mois, davantage de passants s'arrêtaient dans la rue. Comme l'expérience a créé un espace plus convivial, la mairie envisage de l'étendre.","ferramentaTitulo":"cause · conséquence · concession","ferramenta":"Comme/parce que introduisent la cause. Donc/c'est pourquoi expriment la conséquence. Pourtant marque un contraste avec ce qui était attendu.","atividades":[{"tipo":"compréhension","pergunta":"Pourquoi la mairie pense-t-elle étendre l'expérience ?","opcoes":["La rue est devenue plus conviviale","Les voitures sont plus nombreuses","Les plantes coûtent moins cher"],"correta":0,"explicacao":"L'espace attire davantage de passants et paraît plus convivial."},{"tipo":"connecteur","pergunta":"Complète le contraste : Les commerçants étaient inquiets; ___, la fréquentation a augmenté.","respostas":["pourtant","cependant","néanmoins"],"resposta":"pourtant","explicacao":"Pourtant introduit un résultat contraire à la crainte."},{"tipo":"reformulation","pergunta":"Relie avec une conséquence : L'espace est convivial. Les passants s'arrêtent.","respostas":["L'espace est convivial donc les passants s'arrêtent","L'espace est convivial c'est pourquoi les passants s'arrêtent"],"resposta":"L'espace est convivial, donc les passants s'arrêtent.","explicacao":"Donc relie la cause au résultat."},{"tipo":"médiation","pergunta":"Présente l'expérience à un conseil de quartier.","instrucao":"Résume la transformation, la crainte initiale et le résultat réel.","modelo":"Les habitants ont transformé six places de stationnement en espace convivial. Les commerçants craignaient de perdre des clients; pourtant, la fréquentation a augmenté.","checklist":["la transformation","la crainte","le résultat contrasté"]},{"tipo":"débat","pergunta":"Réponds à un habitant opposé au projet.","instrucao":"Reconnais un inconvénient, défends un avantage et propose un compromis.","modelo":"Il est vrai que six places disparaissent. Pourtant, cet espace profite à tous. On pourrait réserver une zone de livraison le matin.","checklist":["une concession","un avantage collectif","un compromis"]},{"tipo":"écoute à trous","pergunta":"Écoute et complète : « Pourtant, davantage de passants s'arrêtent dans ___. »","audio":"Pourtant, davantage de passants s'arrêtent dans la rue.","respostas":["la rue"],"resposta":"la rue","explicacao":"Pourtant marca uma oposição ao resultado esperado.","instrucao":"Ouça e escreva somente as palavras que faltam."},{"tipo":"associations","pergunta":"Relie le connecteur à sa fonction.","pares":[["parce que","cause"],["donc","conséquence"],["pourtant","concession"]]},{"tipo":"traduction","pergunta":"Traduza: O espaço é agradável, por isso as pessoas param.","respostas":["L'espace est agréable donc les gens s'arrêtent","L'espace est agréable c'est pourquoi les gens s'arrêtent"],"resposta":"L'espace est agréable, donc les gens s'arrêtent.","explicacao":"Donc apresenta a consequência."},{"tipo":"mission","pergunta":"Défends une amélioration pour ton quartier.","instrucao":"Présente le problème, ta proposition, un avantage et une objection avec pourtant.","modelo":"Il manque des espaces pour se rencontrer. Je propose un petit jardin public parce qu'il créerait du lien. Le terrain est limité; pourtant, quelques bancs suffiraient déjà.","checklist":["un problème précis","une proposition","cause ou conséquence","une concession"]},{"tipo":"lecture critique","pergunta":"« La rue sera piétonne le samedi. Les commerçants souhaitent une période d'essai ; les habitants demandent un accès pour les livraisons. » Quel compromis répond aux deux demandes ?","opcoes":["Interdire toutes les livraisons définitivement","Tester le dispositif avec des horaires de livraison","Refuser toute période d'essai"],"correta":1,"explicacao":"Une période d'essai et des horaires adaptés tiennent compte des deux demandes."},{"tipo":"grammaire","pergunta":"Complète avec un connecteur de concession : ___ la pluie, les bénévoles ont installé les stands.","respostas":["Malgré"],"resposta":"Malgré","explicacao":"Malgré est suivi d'un nom : malgré la pluie."},{"tipo":"remettre en ordre","pergunta":"Remets dans l'ordre : est / donc / peut / complet / on / plus / s'inscrire / l'atelier / ne.","respostas":["L'atelier est complet donc on ne peut plus s'inscrire"],"resposta":"L'atelier est complet, donc on ne peut plus s'inscrire.","explicacao":"Donc introduit la conséquence du manque de places."},{"tipo":"écoute à trous","pergunta":"Écoute et complète : « Le projet coûte cher, pourtant il pourrait améliorer la vie ___. »","audio":"Le projet coûte cher, pourtant il pourrait améliorer la vie du quartier.","respostas":["du quartier"],"resposta":"du quartier","explicacao":"Pourtant oppose le coût à un bénéfice possible ; pourrait garde une nuance.","instrucao":"Ouça e escreva somente as palavras que faltam."},{"tipo":"écoute ciblée","pergunta":"Écoute la réunion. Quelle décision est prise ?","audio":"Certains veulent fermer la rue toute la semaine, d'autres seulement le dimanche. Pour commencer, nous allons essayer deux samedis, puis demander l'avis des habitants.","opcoes":["Fermer toute la semaine immédiatement","Ne rien essayer","Tester deux samedis et recueillir les avis"],"correta":2,"explicacao":"La décision finale porte sur un essai limité suivi d'une consultation.","instrucao":"Ouça quantas vezes precisar e responda sobre o que foi dito."},{"tipo":"traduction","pergunta":"Traduza: Apesar do custo, apoiamos o projeto.","respostas":["Malgré le coût nous soutenons le projet","Malgré le prix nous soutenons le projet","Malgré le coût on soutient le projet"],"resposta":"Malgré le coût, nous soutenons le projet.","explicacao":"Malgré exprime une concession et se construit ici avec un groupe nominal."},{"tipo":"corriger","pergunta":"Corrige : « Malgré il pleut, nous continuons. » Utilise même si.","respostas":["Même s'il pleut nous continuons"],"resposta":"Même s'il pleut, nous continuons.","explicacao":"Même si introduit une proposition avec un verbe ; malgré exige ici un nom."},{"tipo":"associations","pergunta":"Relie le connecteur à sa fonction.","pares":[["Parce que","Donner une cause"],["Donc","Exprimer une conséquence"],["Pourtant","Opposer deux constats"],["Afin de","Présenter un objectif"]]},{"tipo":"carnet d'écriture","pergunta":"Propose un essai de rue piétonne au conseil de quartier.","instrucao":"Écris 90 à 120 mots : position, deux arguments, une objection reconnue et une solution concrète. Utilise un connecteur de cause, un de conséquence et un de concession.","minPalavras":90,"modelo":"Je suis favorable à une période d'essai parce que notre rue manque d'espaces où se rencontrer. Une circulation réduite permettrait aux enfants de jouer plus tranquillement et aux voisins de discuter. Certains commerçants craignent cependant de perdre des clients. Cette inquiétude mérite une réponse : nous pourrions maintenir les livraisons le matin et installer une signalisation vers les parkings. Je propose donc de tester deux samedis, puis de comparer la fréquentation et de recueillir les avis. Malgré quelques contraintes, cette méthode nous aiderait à décider à partir d'une expérience concrète plutôt que de simples suppositions.","checklist":["J'ai développé deux arguments.","J'ai reconnu une objection et proposé une réponse.","J'ai utilisé des connecteurs et un essai mesurable."]},{"tipo":"atelier oral","oral":true,"pergunta":"Défends une proposition pendant deux minutes.","instrucao":"Sujet : faut-il créer un atelier de réparation dans le quartier ? Présente ton avis, deux raisons, une objection et un compromis. Recommence en réduisant les longues pauses.","audio":"À mon avis, un atelier de réparation serait utile parce qu'il permettrait de partager des compétences. Il faudrait toutefois trouver un local et des bénévoles. Nous pourrions commencer une fois par mois afin d'évaluer les besoins.","modelo":"À mon avis, un atelier de réparation serait utile parce qu'il permettrait de partager des compétences. Il faudrait toutefois trouver un local et des bénévoles. Nous pourrions commencer une fois par mois afin d'évaluer les besoins.","checklist":["J'ai annoncé une position et deux raisons.","J'ai présenté une objection sans la caricaturer.","J'ai terminé par une proposition concrète."]}]},{"id":"francophonie","nivel":"B1","tema":"francophonie et cultures","titulo":"Une langue, plusieurs voix","documentoTitulo":"Le club des expressions","documento":"Dans un club en ligne, des francophones de Dakar, Bruxelles, Montréal et Fort-de-France présentent des expressions de leur région. Les membres découvrent des mots qu'ils n'entendent pas toujours dans les médias. Ce projet, auquel participent aussi des apprenants, montre qu'une langue vivante appartient à toutes les personnes qui la parlent.","ferramentaTitulo":"qui · que · où · auquel","ferramenta":"Les pronoms relatifs relient deux idées. Qui remplace le sujet, que le complément direct, où un lieu ou moment. Auquel suit une préposition construite avec à.","atividades":[{"tipo":"compréhension","pergunta":"Quelle idée principale le projet défend-il ?","opcoes":["Une seule manière de parler est correcte","Le français possède plusieurs voix","Les médias inventent les expressions"],"correta":1,"explicacao":"Le texte valorise la diversité des usages francophones."},{"tipo":"grammaire","pergunta":"Complète : C'est un projet ___ réunit plusieurs régions.","respostas":["qui"],"resposta":"qui","explicacao":"Qui est le sujet du verbe réunit."},{"tipo":"grammaire","pergunta":"Complète : Le club ___ je participe est en ligne.","respostas":["auquel"],"resposta":"auquel","explicacao":"On participe à un club : à + lequel = auquel."},{"tipo":"médiation","pergunta":"Explique le projet du club à ton groupe de français.","instrucao":"Présente les participants, l'activité et l'idée défendue.","modelo":"Des francophones de plusieurs régions partagent leurs expressions avec des apprenants. Le club montre que le français est une langue diverse, parlée de nombreuses façons.","checklist":["qui participe","ce qu'ils font","la valeur du projet"]},{"tipo":"projet final","pergunta":"Crée le plan d'un mini-podcast francophone.","instrucao":"Choisis un lieu, un invité, trois questions et une conclusion personnelle.","modelo":"Épisode : Parler français à Dakar. Invitée : une musicienne locale. Questions : Quels mots utilises-tu dans tes chansons ? Quelles langues entends-tu chaque jour ? Quelle expression veux-tu partager ? Conclusion : la diversité enrichit la langue.","checklist":["un titre et un lieu","un invité","trois questions","une conclusion personnelle"]},{"tipo":"écoute à trous","pergunta":"Écoute et complète : « Une langue vivante appartient à ceux qui ___. »","audio":"Une langue vivante appartient à ceux qui la parlent.","respostas":["la parlent"],"resposta":"la parlent","explicacao":"Qui substitui o sujeito de parlent.","instrucao":"Ouça e escreva somente as palavras que faltam."},{"tipo":"associations","pergunta":"Relie le pronom à sa fonction.","pares":[["qui","sujet"],["que","complément direct"],["où","lieu ou moment"],["auquel","complément avec à"]]},{"tipo":"traduction","pergunta":"Traduza: É um projeto do qual eu participo.","respostas":["C'est un projet auquel je participe"],"resposta":"C'est un projet auquel je participe.","explicacao":"Participer à + lequel forma auquel."},{"tipo":"mission","pergunta":"Présente une voix francophone que tu veux découvrir.","instrucao":"Explique ton choix et formule deux questions pour une personne de cette région.","modelo":"J'aimerais découvrir le français du Québec, qui possède beaucoup d'expressions originales. Quels mots utilises-tu au quotidien ? Y a-t-il une expression que les étrangers comprennent mal ?","checklist":["une région francophone","une justification","un pronom relatif","deux questions"]},{"tipo":"lecture critique","pergunta":"« Dans notre café linguistique, chacun garde son accent. Quand un mot n'est pas compris, on le reformule au lieu de se moquer. » Quel principe le groupe défend-il ?","opcoes":["Un seul accent est accepté","Comprendre et reformuler dans le respect des différences","Il est interdit de poser des questions"],"correta":1,"explicacao":"Le texte valorise la diversité des accents et la recherche de compréhension."},{"tipo":"grammaire","pergunta":"Complète : C'est une expression ___ j'entends souvent à Montréal.","respostas":["que"],"resposta":"que","explicacao":"J'entends cette expression : le pronom relatif remplace le complément direct."},{"tipo":"remettre en ordre","pergunta":"Remets dans l'ordre : où / lieu / rencontre / un / on / c'est / se.","respostas":["C'est un lieu où on se rencontre"],"resposta":"C'est un lieu où on se rencontre.","explicacao":"Où reprend un lieu ; on est le sujet de se rencontre."},{"tipo":"écoute à trous","pergunta":"Écoute et complète : « Le projet auquel je participe réunit des personnes de ___. »","audio":"Le projet auquel je participe réunit des personnes de plusieurs pays.","respostas":["plusieurs pays"],"resposta":"plusieurs pays","explicacao":"Participer à un projet devient le projet auquel je participe.","instrucao":"Ouça e escreva somente as palavras que faltam."},{"tipo":"écoute ciblée","pergunta":"Écoute. Comment la personne résout-elle l'incompréhension ?","audio":"Au début, je ne comprenais pas une expression utilisée par mon collègue. Je lui ai demandé de la reformuler et de donner un exemple. Ensuite, nous avons comparé avec une expression de ma région.","opcoes":["Elle fait semblant de comprendre","Elle demande une reformulation et un exemple","Elle refuse de poursuivre la conversation"],"correta":1,"explicacao":"Demander un exemple permet de comprendre sans juger la manière de parler.","instrucao":"Ouça quantas vezes precisar e responda sobre o que foi dito."},{"tipo":"traduction","pergunta":"Traduza: É o grupo do qual faço parte.","respostas":["C'est le groupe dont je fais partie"],"resposta":"C'est le groupe dont je fais partie.","explicacao":"Faire partie de appelle dont, qui remplace un complément introduit par de."},{"tipo":"corriger","pergunta":"Corrige le relatif : « C'est le festival que je participe chaque année. »","respostas":["C'est le festival auquel je participe chaque année"],"resposta":"C'est le festival auquel je participe chaque année.","explicacao":"On participe à un festival : à + lequel donne auquel."},{"tipo":"associations","pergunta":"Relie chaque début à sa suite grammaticale.","pares":[["Une personne qui…","organise des rencontres."],["Une expression que…","j'utilise souvent."],["Un café où…","nous discutons le jeudi."],["Un projet auquel…","je participe depuis mars."]]},{"tipo":"carnet d'écriture","pergunta":"Rédige la page d'accueil d'un café linguistique.","instrucao":"Écris 90 à 120 mots : présente le lieu, le public, deux activités et une règle d'accueil respectueuse. Utilise qui, que et où. Termine par une invitation précise.","minPalavras":90,"modelo":"Bienvenue au café des langues, un lieu où chacun peut pratiquer sans avoir peur de son accent. Notre équipe accueille les personnes qui souhaitent échanger, quel que soit leur parcours. Nous proposons des conversations en petits groupes et des jeux que les participants choisissent ensemble. Si une expression n'est pas comprise, nous invitons chacun à reformuler ou à donner un exemple. Nous demandons aussi de laisser aux autres le temps de terminer leurs phrases. Venez jeudi à dix-huit heures avec une photo ou un petit objet dont vous aimeriez raconter l'histoire. L'inscription se fait à l'accueil du café.","checklist":["J'ai présenté le lieu, le public et deux activités.","J'ai utilisé correctement qui, que et où.","J'ai formulé une règle respectueuse et une invitation précise."]},{"tipo":"atelier oral","oral":true,"pergunta":"Présente une habitude culturelle sans généraliser.","instrucao":"Parle deux minutes : donne un exemple de ton expérience, compare avec une autre situation et nuance avec dans mon entourage ou certaines personnes. Réponds ensuite à une question imaginaire.","audio":"Dans mon entourage, on aime se retrouver autour d'un repas le dimanche. Cela ne veut pas dire que tout le monde fait la même chose. J'ai aussi des amis qui préfèrent organiser une sortie. Ce qui compte pour nous, c'est de passer du temps ensemble.","modelo":"Dans mon entourage, on aime se retrouver autour d'un repas le dimanche. Cela ne veut pas dire que tout le monde fait la même chose. J'ai aussi des amis qui préfèrent organiser une sortie. Ce qui compte pour nous, c'est de passer du temps ensemble.","checklist":["J'ai donné un exemple personnel précis.","J'ai nuancé mes observations sans généraliser.","J'ai répondu spontanément à une question complémentaire."]}]},{"id":"chemin","nivel":"voyage","tema":"s'orienter en ville","titulo":"Demander son chemin","documentoTitulo":"Un touriste un peu perdu","documento":"Léo cherche la gare, mais son téléphone n'a plus de batterie. Il demande son chemin à une passante : « Excusez-moi, pour aller à la gare, s'il vous plaît ? » Elle répond : « Continuez tout droit, puis tournez à gauche après la pharmacie. La gare est juste en face de la boulangerie. » Léo la remercie et repart, un peu plus confiant.","ferramentaTitulo":"tout droit · à gauche/à droite · en face de","ferramenta":"Ces expressions de lieu indiquent une direction. L'impératif (continuez, tournez) sert à donner des indications de façon polie.","atividades":[{"tipo":"compréhension","pergunta":"Où se trouve la gare, d'après la passante ?","opcoes":["À côté de la pharmacie","En face de la boulangerie","Derrière la gare routière"],"correta":1,"explicacao":"La gare est juste en face de la boulangerie."},{"tipo":"lexique","pergunta":"Complète : Pour ___ à la gare, s'il vous plaît ?","respostas":["aller"],"resposta":"aller","explicacao":"« Pour aller à » + lieu est la formule classique pour demander un chemin."},{"tipo":"grammaire","pergunta":"Transforme en impératif poli (vous) : tourner à gauche.","respostas":["Tournez à gauche"],"resposta":"Tournez à gauche.","explicacao":"L'impératif à la 2e personne du pluriel donne une instruction polie."},{"tipo":"médiation","pergunta":"Explique à un ami non francophone comment aller de la pharmacie à la gare.","instrucao":"Utilise au moins deux indications de direction.","modelo":"Continue tout droit, puis tourne à gauche après la pharmacie. La gare est en face de la boulangerie.","checklist":["deux indications de direction","un repère (pharmacie/boulangerie)","phrase claire"]},{"tipo":"interaction","pergunta":"Prépare trois façons différentes de demander son chemin.","instrucao":"Varie la politesse et la formulation.","modelo":"Excusez-moi, pour aller à la gare, s'il vous plaît ? / Vous savez où se trouve la poste ? / Est-ce que la banque est loin d'ici ?","checklist":["trois formulations","au moins une avec « excusez-moi »","vocabulaire de lieu"]},{"tipo":"écoute à trous","pergunta":"Écoute et complète : « Continuez tout droit, puis tournez ___. »","audio":"Continuez tout droit, puis tournez à gauche.","respostas":["à gauche"],"resposta":"à gauche","explicacao":"« Tout droit » indica seguir em frente sem virar.","instrucao":"Ouça e escreva somente as palavras que faltam."},{"tipo":"associations","pergunta":"Relie les mots à leur sens.","pares":[["tout droit","em linha reta"],["à gauche","direção esquerda"],["en face de","posição oposta"],["au coin de","na esquina de"]]},{"tipo":"traduction","pergunta":"Traduza: Onde fica o banheiro, por favor?","respostas":["Où sont les toilettes, s'il vous plaît","Où se trouvent les toilettes, s'il vous plaît"],"resposta":"Où sont les toilettes, s'il vous plaît ?","explicacao":"« Où sont/se trouvent » pergunta localização."},{"tipo":"mission","pergunta":"Você está perdido numa cidade francesa. Peça informação e reaja à resposta.","instrucao":"Escreva a pergunta e uma reação educada à resposta recebida.","modelo":"Excusez-moi, pour aller à la station de métro la plus proche ? / Merci beaucoup, c'est très gentil !","checklist":["pergunta educada","reação de agradecimento","vocabulário de direção"]}]},{"id":"restaurant","nivel":"voyage","tema":"commander un repas","titulo":"Au restaurant","documentoTitulo":"Une commande simple","documento":"Au restaurant, la serveuse demande : « Vous avez choisi ? » Camille répond : « Oui, je voudrais une salade et le poisson du jour, s'il vous plaît. » Son ami préfère un plat végétarien et demande : « Est-ce qu'il y a des plats sans viande ? » La serveuse leur conseille les légumes grillés. À la fin, ils demandent l'addition.","ferramentaTitulo":"je voudrais · est-ce qu'il y a · l'addition","ferramenta":"« Je voudrais » + nom/infinitif exprime une demande polie. « Est-ce qu'il y a... ? » sert à demander la disponibilité de quelque chose.","atividades":[{"tipo":"compréhension","pergunta":"Que demande l'ami de Camille ?","opcoes":["L'addition tout de suite","Un plat sans viande","Le poisson du jour"],"correta":1,"explicacao":"Il demande s'il y a des plats sans viande."},{"tipo":"lexique","pergunta":"Complète : Je ___ une salade, s'il vous plaît.","respostas":["voudrais"],"resposta":"voudrais","explicacao":"« Je voudrais » est plus poli que « je veux »."},{"tipo":"grammaire","pergunta":"Transforme en question polie : il y a des plats sans viande.","respostas":["Est-ce qu'il y a des plats sans viande"],"resposta":"Est-ce qu'il y a des plats sans viande ?","explicacao":"« Est-ce que » transforme une affirmation en question."},{"tipo":"médiation","pergunta":"Explique à un ami ce que Camille et son ami ont commandé.","instrucao":"Mentionne les deux plats et la demande finale.","modelo":"Camille a commandé une salade et le poisson du jour. Son ami a préféré des légumes grillés. Ils ont demandé l'addition à la fin.","checklist":["les deux commandes","la demande finale","phrases complètes"]},{"tipo":"interaction","pergunta":"Prépare un mini-dialogue pour commander au restaurant.","instrucao":"Inclue une question du serveur et ta réponse.","modelo":"— Vous avez choisi ? — Oui, je voudrais le plat du jour et une eau minérale, s'il vous plaît.","checklist":["question du serveur","réponse polie","un plat + une boisson"]},{"tipo":"écoute à trous","pergunta":"Écoute et complète : « Je voudrais l'addition, s'il ___. »","audio":"Je voudrais l'addition, s'il vous plaît.","respostas":["vous plaît"],"resposta":"vous plaît","explicacao":"Frase comum pra pedir a conta.","instrucao":"Ouça e escreva somente as palavras que faltam."},{"tipo":"associations","pergunta":"Relie les mots à leur sens.","pares":[["l'addition","conta"],["le plat du jour","prato do dia"],["sans viande","sem carne"],["à point","ao ponto (carne)"]]},{"tipo":"traduction","pergunta":"Traduza: Vocês têm pratos vegetarianos?","respostas":["Est-ce que vous avez des plats végétariens","Vous avez des plats végétariens"],"resposta":"Est-ce que vous avez des plats végétariens ?","explicacao":"Pergunta educada sobre opções do cardápio."},{"tipo":"mission","pergunta":"Escreva um pedido completo num restaurante francês.","instrucao":"Inclua um prato, uma bebida e um pedido educado extra.","modelo":"Je voudrais le poisson du jour et un jus d'orange, s'il vous plaît. Est-ce que je pourrais avoir du pain ?","checklist":["um prato","uma bebida","um pedido extra educado"]}]},{"id":"heure","nivel":"voyage","tema":"l'heure et les horaires","titulo":"Quelle heure est-il ?","documentoTitulo":"Un rendez-vous à ne pas manquer","documento":"Inès doit prendre son train à 14h30. Il est déjà 13h45 et elle demande à un passant : « Excusez-moi, quelle heure est-il ? » Il répond : « Il est deux heures moins le quart. » Inès presse le pas : elle a encore le temps, mais il ne faut pas traîner. Le train part dans quarante-cinq minutes.","ferramentaTitulo":"il est ... heures · moins le quart · dans + durée","ferramenta":"Pour dire l'heure : il est + nombre + heures. « Moins le quart » = 15 minutes avant l'heure pleine. « Dans » + durée indique un moment futur proche.","atividades":[{"tipo":"compréhension","pergunta":"À quelle heure part le train d'Inès ?","opcoes":["13h45","14h30","14h45"],"correta":1,"explicacao":"Elle doit prendre son train à 14h30."},{"tipo":"lexique","pergunta":"Complète : Il est deux heures ___ le quart.","respostas":["moins"],"resposta":"moins","explicacao":"« Moins le quart » indica 15 minutos antes da hora cheia."},{"tipo":"grammaire","pergunta":"Escreva por extenso: 14h30.","respostas":["il est deux heures et demie","il est quatorze heures trente"],"resposta":"Il est deux heures et demie.","explicacao":"« Et demie » indica 30 minutos."},{"tipo":"médiation","pergunta":"Explique à un ami à quelle heure Inès doit partir et pourquoi elle se dépêche.","instrucao":"Mentionne l'heure actuelle et l'heure du train.","modelo":"Il est presque deux heures et le train d'Inès part à deux heures et demie. Elle se dépêche parce qu'il ne reste que peu de temps.","checklist":["heure actuelle","heure du train","raison de se dépêcher"]},{"tipo":"interaction","pergunta":"Prépare trois façons de demander l'heure ou un horaire.","instrucao":"Varie entre l'heure et un horaire de transport.","modelo":"Quelle heure est-il, s'il vous plaît ? / Vous savez à quelle heure part le prochain bus ? / Le musée ouvre à quelle heure ?","checklist":["trois questions","vocabulaire de l'heure","politesse"]},{"tipo":"écoute à trous","pergunta":"Écoute et complète : « Il est deux heures moins ___. »","audio":"Il est deux heures moins le quart.","respostas":["le quart"],"resposta":"le quart","explicacao":"Expressão comum pra dizer as horas.","instrucao":"Ouça e escreva somente as palavras que faltam."},{"tipo":"associations","pergunta":"Relie les expressions à leur sens.","pares":[["et quart","15 minutos depois"],["et demie","30 minutos depois"],["moins le quart","15 minutos antes"],["pile","exatamente"]]},{"tipo":"traduction","pergunta":"Traduza: A que horas o museu fecha?","respostas":["À quelle heure ferme le musée","Le musée ferme à quelle heure"],"resposta":"À quelle heure ferme le musée ?","explicacao":"Pergunta sobre horário de funcionamento."},{"tipo":"mission","pergunta":"Você tem um compromisso em 20 minutos. Escreva o que diria pra confirmar o horário e se apressar.","instrucao":"Inclua uma pergunta sobre a hora e uma frase sobre pressa.","modelo":"Excusez-moi, quelle heure est-il ? Il faut que je me dépêche, mon rendez-vous est dans vingt minutes !","checklist":["pergunta sobre a hora","expressão de pressa","frase natural"]}]},{"id":"hotel","nivel":"voyage","tema":"s'installer à l'hôtel","titulo":"À l'hôtel","documentoTitulo":"Arrivée à l'hôtel","documento":"Sarah arrive à l'hôtel après un long voyage. Elle dit à la réception : « Bonjour, j'ai une réservation au nom de Sarah Dubois. » L'employé vérifie et répond : « Parfait, votre chambre est au troisième étage. Voici la clé. » Sarah demande aussi si le petit-déjeuner est inclus et à quelle heure il est servi. L'employé lui explique que c'est de sept heures à dix heures, dans la salle à côté du hall.","ferramentaTitulo":"j'ai une réservation · au nom de · est-ce inclus","ferramenta":"« Au nom de » indique la personne titulaire d'une réservation. « Est-ce que c'est inclus ? » sert à demander si quelque chose fait partie du prix.","atividades":[{"tipo":"compréhension","pergunta":"À quel étage se trouve la chambre de Sarah ?","opcoes":["Premier étage","Deuxième étage","Troisième étage"],"correta":2,"explicacao":"Sa chambre est au troisième étage."},{"tipo":"lexique","pergunta":"Complète : J'ai une réservation ___ nom de Sarah Dubois.","respostas":["au"],"resposta":"au","explicacao":"« Au nom de » + prénom/nom indica o titular da reserva."},{"tipo":"grammaire","pergunta":"Transforme en question : le petit-déjeuner est inclus.","respostas":["Est-ce que le petit-déjeuner est inclus"],"resposta":"Est-ce que le petit-déjeuner est inclus ?","explicacao":"« Est-ce que » transforma afirmação em pergunta."},{"tipo":"médiation","pergunta":"Explique a alguém o que Sarah perguntou e o que descobriu sobre o café da manhã.","instrucao":"Mencione o horário e o local.","modelo":"Sarah a demandé si le petit-déjeuner était inclus. L'employé lui a dit qu'il est servi de sept heures à dix heures, dans la salle à côté du hall.","checklist":["horário","local","frase completa"]},{"tipo":"interaction","pergunta":"Prépare ce que tu dirais à la réception d'un hôtel.","instrucao":"Inclue ton nom et une question sur les services.","modelo":"Bonjour, j'ai une réservation au nom de Ana Silva. Est-ce qu'il y a le wifi gratuit dans les chambres ?","checklist":["apresentação com nome","pergunta sobre serviço","tom educado"]},{"tipo":"écoute à trous","pergunta":"Écoute et complète : « J'ai une réservation au nom de ___. »","audio":"J'ai une réservation au nom de Sarah Dubois.","respostas":["Sarah Dubois"],"resposta":"Sarah Dubois","explicacao":"Frase padrão pra check-in.","instrucao":"Ouça e escreva somente as palavras que faltam."},{"tipo":"associations","pergunta":"Relie les mots à leur sens.","pares":[["la réception","recepção"],["la clé","chave"],["inclus","incluído"],["le hall","saguão/hall"]]},{"tipo":"traduction","pergunta":"Traduza: Eu gostaria de trocar de quarto, por favor.","respostas":["Je voudrais changer de chambre, s'il vous plaît"],"resposta":"Je voudrais changer de chambre, s'il vous plaît.","explicacao":"Pedido educado usando « je voudrais »."},{"tipo":"mission","pergunta":"Escreva uma reclamação educada sobre um problema no quarto do hotel (ex: barulho, ar-condicionado).","instrucao":"Inclua o problema e um pedido de solução.","modelo":"Bonjour, il y a un problème dans ma chambre : la climatisation ne fonctionne pas. Est-ce que quelqu'un pourrait venir la réparer ?","checklist":["problema mencionado","pedido de solução","tom educado"]}]},{"id":"arrivee_paris","nivel":"Paris","tema":"aéroport · gare · transfert","titulo":"Arriver à Paris","documentoTitulo":"De l'aéroport au centre","documento":"À l'aéroport Charles-de-Gaulle, Nora cherche le train pour Paris. Elle demande à un agent : « Bonjour, où puis-je acheter un billet pour le RER B ? » L'agent répond : « Aux distributeurs, juste à droite. Suivez ensuite les panneaux Paris par train. » Nora demande : « Est-ce que ce billet est valable jusqu'à Châtelet ? » L'agent confirme et lui rappelle de garder son ticket jusqu'à la sortie.","ferramentaTitulo":"billet · aller simple · correspondance · sortie","ferramenta":"Un aller simple est un trajet sans retour. Une correspondance est un changement de ligne. À Paris, gardez votre ticket ou passe jusqu'à la sortie et vérifiez toujours la destination affichée.","atividades":[{"tipo":"compréhension","pergunta":"Où Nora achète-t-elle son billet ?","opcoes":["Dans le train","Aux distributeurs","Chez le chauffeur"],"correta":1,"explicacao":"L'agent indique les distributeurs situés à droite."},{"tipo":"lexique","pergunta":"Complète : Je voudrais un ___ simple pour Paris.","respostas":["aller"],"resposta":"aller","explicacao":"Un aller simple ne comprend pas le trajet de retour."},{"tipo":"grammaire","pergunta":"Pose poliment la question avec pouvoir : Où acheter un billet ?","respostas":["Où puis-je acheter un billet","Où est-ce que je peux acheter un billet"],"resposta":"Où puis-je acheter un billet ?","explicacao":"« Puis-je » est une forme polie de « je peux »."},{"tipo":"médiation","pergunta":"Explique à un ami comment rejoindre Paris depuis l'aéroport.","instrucao":"Mentionne le billet, les panneaux et la destination.","modelo":"Achète un billet pour Paris au distributeur, suis les panneaux « Paris par train » et vérifie que le RER va vers le centre.","checklist":["où acheter le billet","quel panneau suivre","vérifier la destination"]},{"tipo":"interaction","pergunta":"Demande un transfert vers ton hôtel.","instrucao":"Demande le moyen de transport, le prix et la durée.","modelo":"Bonjour, quel est le moyen le plus simple pour aller à mon hôtel ? Combien coûte le trajet et combien de temps faut-il ?","checklist":["destination","prix","durée"]},{"tipo":"compréhension orale","pergunta":"Écoute. Que faut-il garder jusqu'à la sortie ?","audio":"Gardez votre ticket jusqu'à la sortie.","opcoes":["Le ticket","Le passeport","Le bagage"],"correta":0,"explicacao":"Il faut garder le ticket jusqu'à la sortie.","instrucao":"Ouça quantas vezes precisar e responda sobre o que foi dito."},{"tipo":"associations","pergunta":"Relie chaque mot à son sens.","pares":[["un aller simple","só ida"],["un aller-retour","ida e volta"],["une correspondance","baldeação"],["la sortie","saída"]]},{"tipo":"traduction","pergunta":"Traduza: Este trem vai para o centro de Paris?","respostas":["Est-ce que ce train va au centre de Paris","Ce train va au centre de Paris"],"resposta":"Est-ce que ce train va au centre de Paris ?","explicacao":"« Aller à/au » indica o destino."},{"tipo":"mission","pergunta":"Você acabou de chegar a Paris e precisa chegar ao hotel.","instrucao":"Escreva um diálogo curto com um funcionário do aeroporto.","modelo":"— Bonjour, pour aller à Bastille, je prends le RER B ? — Oui, puis changez à Châtelet. — Où puis-je acheter le billet ? — Aux distributeurs à droite.","checklist":["saudação","destino","bilhete","confirmação do trajeto"]}]},{"id":"metro_paris","nivel":"Paris","tema":"métro · RER · bus","titulo":"Prendre le métro","documentoTitulo":"Une correspondance à République","documento":"Dans le métro, Amir lit le plan et hésite. Il demande : « Pour aller à Nation, je prends bien la ligne 9 direction Mairie de Montreuil ? » Une voyageuse répond : « Oui, mais aujourd'hui la ligne est interrompue entre République et Oberkampf. Prenez la ligne 3, puis changez à Père Lachaise. » Amir la remercie et regarde le quai indiqué.","ferramentaTitulo":"direction · quai · terminus · ligne interrompue","ferramenta":"La direction d'une ligne est indiquée par son terminus. « Trafic interrompu » signifie que les trains ne circulent pas sur une partie de la ligne. « Descendre à » indique la station de sortie.","atividades":[{"tipo":"compréhension","pergunta":"Pourquoi Amir doit-il changer d'itinéraire ?","opcoes":["La station est fermée définitivement","La ligne 9 est partiellement interrompue","Il a perdu son ticket"],"correta":1,"explicacao":"La circulation est interrompue entre deux stations."},{"tipo":"lexique","pergunta":"Complète : La dernière station d'une ligne est le ___.","respostas":["terminus"],"resposta":"terminus","explicacao":"Le terminus donne le nom de la direction du métro."},{"tipo":"grammaire","pergunta":"Complète : Descendez ___ République et changez ___ ligne.","respostas":["à, de","à de"],"resposta":"à République et changez de ligne.","explicacao":"On descend à une station et on change de ligne."},{"tipo":"médiation","pergunta":"Explique un itinéraire avec une correspondance.","instrucao":"Indique la ligne, la direction, la station de changement et la sortie.","modelo":"Prenez la ligne 4 direction Bagneux, changez à Châtelet pour la ligne 1 direction La Défense et descendez à Louvre-Rivoli.","checklist":["deux lignes","deux directions","station de correspondance"]},{"tipo":"interaction","pergunta":"Demande si tu es sur le bon quai.","instrucao":"Précise ta destination et confirme la direction.","modelo":"Excusez-moi, c'est bien ce quai pour aller à Gare de Lyon ? Je dois prendre la direction Château de Vincennes ?","checklist":["formule polie","destination","direction"]},{"tipo":"compréhension orale","pergunta":"Écoute l'annonce. Quelle ligne est interrompue ?","audio":"Attention, le trafic est interrompu sur la ligne douze.","opcoes":["La ligne 2","La ligne 12","La ligne 14"],"correta":1,"explicacao":"L'annonce indique que la ligne 12 est interrompue.","instrucao":"Ouça quantas vezes precisar e responda sobre o que foi dito."},{"tipo":"associations","pergunta":"Relie l'information à l'action.","pares":[["sortie 2","prendre la deuxième sortie"],["correspondance","changer de ligne"],["direction","regarder le terminus"],["quai","attendre le train"]]},{"tipo":"traduction","pergunta":"Traduza: Em qual estação eu devo descer?","respostas":["À quelle station dois-je descendre","Je dois descendre à quelle station"],"resposta":"À quelle station dois-je descendre ?","explicacao":"« Devoir + infinitif » pergunta a ação necessária."},{"tipo":"mission","pergunta":"Planeje um trajeto de metrô em Paris e peça confirmação.","instrucao":"Inclua linha, direção, troca e estação final.","modelo":"Je prends la ligne 1 direction La Défense, je change à Charles de Gaulle–Étoile et je prends la ligne 6. Je descends à Bir-Hakeim, c'est bien ça ?","checklist":["linha","direção","correspondência","confirmação"]}]},{"id":"panneaux_rues","nivel":"Paris","tema":"panneaux · rues · espace public","titulo":"Lire les rues et les panneaux","documentoTitulo":"Autour de l'Hôtel de Ville","documento":"Maya marche dans Paris. Elle voit « Rue barrée », puis « Déviation piétons ». Au coin, une plaque indique « rue de Rivoli — 4e arrondissement ». Elle demande à un passant : « Le trottoir d'en face est accessible ? » Il répond : « Oui, traversez au passage piéton. Attention, cette rue est à sens unique et il y a des travaux. »","ferramentaTitulo":"rue · avenue · boulevard · quai · impasse","ferramenta":"Une rue est une voie urbaine; une avenue est souvent large; un boulevard est un grand axe; un quai longe généralement la Seine; une impasse n'a pas de sortie. Les plaques bleues donnent le nom de la voie et l'arrondissement.","atividades":[{"tipo":"compréhension","pergunta":"Que doit faire Maya à cause de la rue barrée ?","opcoes":["Suivre la déviation piétons","Marcher sur la chaussée","Entrer dans l'impasse"],"correta":0,"explicacao":"Le panneau indique une déviation réservée aux piétons."},{"tipo":"lexique","pergunta":"Complète : Une rue sans sortie est une ___.","respostas":["impasse"],"resposta":"impasse","explicacao":"Une impasse se termine sans déboucher sur une autre rue."},{"tipo":"grammaire","pergunta":"Transforme en consigne : Vous traversez au passage piéton.","respostas":["Traversez au passage piéton"],"resposta":"Traversez au passage piéton.","explicacao":"L'impératif de vous supprime le pronom sujet."},{"tipo":"médiation","pergunta":"Explique ces panneaux à un ami : sens interdit, travaux, sortie de secours.","instrucao":"Donne une action adaptée pour chaque panneau.","modelo":"« Sens interdit » : n'entre pas par cette rue. « Travaux » : ralentis et suis la déviation. « Sortie de secours » : garde le passage libre.","checklist":["trois panneaux","trois actions","phrases claires"]},{"tipo":"interaction","pergunta":"Demande où commence une rue et si elle est loin.","instrucao":"Utilise un repère visible.","modelo":"Excusez-moi, où commence la rue Mouffetard ? C'est loin d'ici ? Est-ce près de la place ?","checklist":["nom de rue","distance","repère"]},{"tipo":"écoute à trous","pergunta":"Écoute et complète : « Traversez la place et prenez la deuxième rue ___. »","audio":"Traversez la place et prenez la deuxième rue à droite.","respostas":["à droite"],"resposta":"à droite","explicacao":"« La deuxième rue » conta as ruas a partir do ponto atual.","instrucao":"Ouça e escreva somente as palavras que faltam."},{"tipo":"associations","pergunta":"Relie la voie à sa description.","pares":[["un quai","longe la Seine"],["une impasse","n'a pas de sortie"],["un boulevard","grand axe urbain"],["un trottoir","espace pour les piétons"]]},{"tipo":"traduction","pergunta":"Traduza: A rua está fechada por causa das obras.","respostas":["La rue est fermée à cause des travaux","La rue est barrée à cause des travaux"],"resposta":"La rue est fermée à cause des travaux.","explicacao":"« À cause de » introduz uma causa geralmente negativa."},{"tipo":"mission","pergunta":"Você vê uma placa que não entende em Paris.","instrucao":"Leia a placa, peça explicação e confirme o que deve fazer.","modelo":"Excusez-moi, que signifie « accès interdit » ? Je dois passer par l'autre rue, c'est bien ça ?","checklist":["citar a placa","pedir significado","confirmar ação"]}]},{"id":"boulangerie_cafe","nivel":"Paris","tema":"boulangerie · café · politesse","titulo":"À la boulangerie et au café","documentoTitulo":"Un petit-déjeuner au comptoir","documento":"Dans une boulangerie, Sofia attend son tour. Elle dit : « Bonjour, je vais vous prendre une tradition, deux croissants et un café allongé, s'il vous plaît. » La vendeuse demande : « Sur place ou à emporter ? » Sofia répond : « Sur place. Et je peux avoir un verre d'eau ? » Elle paie sans contact et dit au revoir avant de s'installer.","ferramentaTitulo":"je vais prendre · sur place · à emporter · l'addition","ferramenta":"À Paris, dire bonjour avant de commander est essentiel. « Je vais prendre » et « je voudrais » sont naturels. Au comptoir, on précise si l'on consomme sur place ou à emporter.","atividades":[{"tipo":"compréhension","pergunta":"Où Sofia va-t-elle consommer ?","opcoes":["Dans la rue","Sur place","Dans le métro"],"correta":1,"explicacao":"Elle répond clairement « sur place »."},{"tipo":"lexique","pergunta":"Complète : Un café moins fort avec plus d'eau est un café ___.","respostas":["allongé"],"resposta":"allongé","explicacao":"Un café allongé contient davantage d'eau qu'un expresso."},{"tipo":"grammaire","pergunta":"Commande poliment une baguette avec vouloir.","respostas":["Je voudrais une baguette s'il vous plaît","Je voudrais une baguette"],"resposta":"Je voudrais une baguette, s'il vous plaît.","explicacao":"Le conditionnel « voudrais » adoucit la demande."},{"tipo":"médiation","pergunta":"Explique à un ami comment commander dans une boulangerie parisienne.","instrucao":"Mentionne la salutation, la commande et le mode de consommation.","modelo":"Dis bonjour, commande avec « je voudrais », précise « sur place » ou « à emporter », puis remercie et dis au revoir.","checklist":["bonjour","commande polie","sur place/à emporter"]},{"tipo":"interaction","pergunta":"Commande un petit-déjeuner et demande une alternative sans lait.","instrucao":"Demande aussi le prix.","modelo":"Bonjour, je voudrais un croissant et un café au lait d'avoine. Vous avez une option sans lait ? Ça fait combien, s'il vous plaît ?","checklist":["commande","besoin alimentaire","prix"]},{"tipo":"compréhension orale","pergunta":"Écoute. Que demande la vendeuse ?","audio":"Vous désirez autre chose ?","opcoes":["Si le client veut autre chose","Si le client paie par carte","Si la commande est à emporter"],"correta":0,"explicacao":"La vendeuse demande si le client souhaite ajouter quelque chose.","instrucao":"Ouça quantas vezes precisar e responda sobre o que foi dito."},{"tipo":"associations","pergunta":"Relie l'expression à la situation.","pares":[["sur place","consommer ici"],["à emporter","emportar o pedido"],["un café serré","café curto e forte"],["ça fait combien ?","perguntar o total"]]},{"tipo":"traduction","pergunta":"Traduza: Eu posso pagar sem contato?","respostas":["Je peux payer sans contact","Est-ce que je peux payer sans contact"],"resposta":"Est-ce que je peux payer sans contact ?","explicacao":"« Payer sans contact » é pagar por aproximação."},{"tipo":"mission","pergunta":"Faça um pedido completo num café parisiense.","instrucao":"Inclua saudação, bebida, comida, preferência e pagamento.","modelo":"Bonjour, je vais prendre un café crème et un pain au chocolat, sur place. Sans sucre, s'il vous plaît. Je peux payer par carte ?","checklist":["saudação","pedido","preferência","pagamento"]}]},{"id":"achats_paiement","nivel":"Paris","tema":"boutiques · tailles · paiement","titulo":"Faire des achats","documentoTitulo":"Dans une boutique du Marais","documento":"Clara essaie une veste. Elle demande : « Vous l'avez en taille 38 ou dans une autre couleur ? » Le vendeur apporte un modèle bleu et précise : « Les cabines sont au fond. » Après l'essayage, Clara dit : « Elle me va bien, mais est-ce que je peux l'échanger si nécessaire ? » Le vendeur lui explique qu'elle doit garder le ticket de caisse.","ferramentaTitulo":"taille · cabine · ticket de caisse · échange","ferramenta":"« Je fais du 38 » indique la taille. « Ça me va » parle de la coupe. Pour un échange ou un remboursement, demandez les conditions et gardez le ticket de caisse.","atividades":[{"tipo":"compréhension","pergunta":"Que doit garder Clara pour échanger la veste ?","opcoes":["L'étiquette du prix seulement","Le ticket de caisse","Le sac du magasin"],"correta":1,"explicacao":"Le vendeur demande de conserver le ticket de caisse."},{"tipo":"lexique","pergunta":"Complète : Où sont les cabines d'___ ?","respostas":["essayage"],"resposta":"essayage","explicacao":"La cabine d'essayage est l'endroit où l'on essaie un vêtement."},{"tipo":"grammaire","pergunta":"Remplace la veste par un pronom : Vous avez la veste en bleu ?","respostas":["Vous l'avez en bleu"],"resposta":"Vous l'avez en bleu ?","explicacao":"Le pronom COD féminin « la » devient « l' » devant une voyelle."},{"tipo":"médiation","pergunta":"Explique les conditions d'échange à un ami.","instrucao":"Mentionne délai, état du produit et justificatif.","modelo":"Tu peux échanger l'article sous trente jours s'il n'a pas été porté. Garde l'étiquette et le ticket de caisse.","checklist":["délai","état du produit","ticket"]},{"tipo":"interaction","pergunta":"Demande une autre taille et essaie de résoudre un problème de prix.","instrucao":"Reste poli et précis.","modelo":"Excusez-moi, vous avez ce pantalon en taille 40 ? Le prix affiché en rayon était différent : pourriez-vous vérifier ?","checklist":["taille","problème de prix","demande polie"]},{"tipo":"écoute à trous","pergunta":"Écoute et complète : « Vous pouvez l'échanger sous trente jours avec ___. »","audio":"Vous pouvez l'échanger sous trente jours avec le ticket.","respostas":["le ticket"],"resposta":"le ticket","explicacao":"« Sous trente jours » indica o prazo máximo.","instrucao":"Ouça e escreva somente as palavras que faltam."},{"tipo":"associations","pergunta":"Relie chaque terme à son usage.","pares":[["une taille","medida da roupa"],["une cabine","local para provar"],["un reçu","comprovante"],["un remboursement","devolução do dinheiro"]]},{"tipo":"traduction","pergunta":"Traduza: Posso experimentar este casaco?","respostas":["Est-ce que je peux essayer ce manteau","Je peux essayer ce manteau"],"resposta":"Est-ce que je peux essayer ce manteau ?","explicacao":"« Essayer » significa experimentar uma roupa."},{"tipo":"mission","pergunta":"Compre uma roupa e tire três dúvidas antes de pagar.","instrucao":"Pergunte tamanho, provador e troca.","modelo":"Vous avez cette chemise en taille M ? Où sont les cabines d'essayage ? Et est-ce que je peux l'échanger si elle ne va pas ?","checklist":["taille","cabine","échange"]}]},{"id":"musees_monuments","nivel":"Paris","tema":"visites · billets · horaires","titulo":"Visiter les musées et monuments","documentoTitulo":"Une visite au musée","documento":"Devant un musée, Lucas montre sa réservation. L'agente lui dit : « Votre créneau est à 15 heures. L'entrée se trouve sous la pyramide et les grands sacs doivent rester au vestiaire. » Lucas demande : « Est-ce que les photos sans flash sont autorisées ? » Elle répond : « Oui, sauf dans les salles signalées. Le musée ferme à 18 heures, mais l'évacuation commence à 17h30. »","ferramentaTitulo":"créneau · vestiaire · plein tarif · tarif réduit","ferramenta":"Un créneau est une heure de visite réservée. Le plein tarif est le prix normal; le tarif réduit concerne certains publics. « Sauf » introduit une exception.","atividades":[{"tipo":"compréhension","pergunta":"À quelle heure commence l'évacuation ?","opcoes":["À 15 heures","À 17h30","À 18h30"],"correta":1,"explicacao":"Le musée ferme à 18 heures mais l'évacuation commence trente minutes avant."},{"tipo":"lexique","pergunta":"Complète : Je dois laisser mon sac au ___.","respostas":["vestiaire"],"resposta":"vestiaire","explicacao":"Le vestiaire garde les sacs et manteaux pendant la visite."},{"tipo":"grammaire","pergunta":"Exprime l'exception : Les photos sont autorisées, pas dans cette salle.","respostas":["Les photos sont autorisées sauf dans cette salle"],"resposta":"Les photos sont autorisées, sauf dans cette salle.","explicacao":"« Sauf » exclut un élément de la règle générale."},{"tipo":"médiation","pergunta":"Résume les règles du musée à ton groupe.","instrucao":"Mentionne sacs, photos et heure de fermeture.","modelo":"Laissez les grands sacs au vestiaire. Les photos sans flash sont autorisées sauf indication contraire. Revenez vers la sortie avant 17h30.","checklist":["sacs","photos","horaire"]},{"tipo":"interaction","pergunta":"Achète un billet et demande les conditions de visite.","instrucao":"Demande tarif, durée et accès.","modelo":"Bonjour, je voudrais un billet pour aujourd'hui. Y a-t-il un tarif réduit ? Combien de temps dure la visite et où se trouve l'entrée ?","checklist":["billet","tarif","durée ou entrée"]},{"tipo":"écoute à trous","pergunta":"Écoute et complète : « Les photos sont autorisées, mais ___. »","audio":"Les photos sont autorisées, mais sans flash.","respostas":["sans flash"],"resposta":"sans flash","explicacao":"« Sans flash » indica a restrição aplicável às fotos.","instrucao":"Ouça e escreva somente as palavras que faltam."},{"tipo":"associations","pergunta":"Relie le mot à sa définition.","pares":[["un créneau","horário reservado"],["le vestiaire","guarda-volumes"],["le tarif réduit","preço com desconto"],["complet","sem vagas"]]},{"tipo":"traduction","pergunta":"Traduza: Ainda há ingressos para hoje?","respostas":["Il reste des billets pour aujourd'hui","Est-ce qu'il reste des billets pour aujourd'hui"],"resposta":"Est-ce qu'il reste des billets pour aujourd'hui ?","explicacao":"« Il reste » pergunta o que ainda está disponível."},{"tipo":"mission","pergunta":"Organize uma visita a um monument de Paris.","instrucao":"Pergunte horário, ingresso, fila e acessibilidade.","modelo":"Bonjour, quels sont les horaires aujourd'hui ? Faut-il réserver un créneau ? Où commence la file et l'accès est-il adapté aux personnes à mobilité réduite ?","checklist":["horário","reserva","fila","acessibilidade"]}]},{"id":"pharmacie_sante","nivel":"Paris","tema":"pharmacie · symptômes · soins","titulo":"À la pharmacie","documentoTitulo":"Demander conseil au pharmacien","documento":"Emma entre dans une pharmacie et dit : « Bonjour, j'ai mal à la gorge et je tousse depuis hier. Je n'ai pas de fièvre. Qu'est-ce que vous me conseillez ? » Le pharmacien demande : « Vous avez des allergies ou un traitement en cours ? » Emma répond que non. Il lui explique la dose et ajoute : « Si les symptômes s'aggravent, consultez un médecin. »","ferramentaTitulo":"j'ai mal à · depuis · ordonnance · dose","ferramenta":"Pour décrire un symptôme, utilisez « j'ai mal à », « je tousse » ou « j'ai de la fièvre ». « Depuis » indique le début d'un état qui continue. Signalez toujours allergies et traitements.","atividades":[{"tipo":"compréhension","pergunta":"Depuis quand Emma tousse-t-elle ?","opcoes":["Depuis une semaine","Depuis hier","Depuis ce matin seulement"],"correta":1,"explicacao":"Emma dit qu'elle tousse depuis hier."},{"tipo":"lexique","pergunta":"Complète : Pour certains médicaments, il faut une ___.","respostas":["ordonnance"],"resposta":"ordonnance","explicacao":"Une ordonnance est la prescription écrite par un médecin."},{"tipo":"grammaire","pergunta":"Complète avec depuis : Je suis malade ___ deux jours.","respostas":["depuis"],"resposta":"depuis","explicacao":"« Depuis » accompagne une durée qui continue au présent."},{"tipo":"médiation","pergunta":"Explique les symptômes d'un ami au pharmacien.","instrucao":"Précise durée, intensité et allergies.","modelo":"Il a mal au ventre depuis ce matin. La douleur est assez forte et il est allergique à l'aspirine.","checklist":["symptôme","durée","allergie"]},{"tipo":"interaction","pergunta":"Demande un conseil et vérifie comment prendre le médicament.","instrucao":"Pose au moins trois questions.","modelo":"Qu'est-ce que vous me conseillez ? Combien de fois par jour dois-je le prendre ? Avant ou après le repas ? Y a-t-il des effets secondaires ?","checklist":["conseil","dose","moment de prise"]},{"tipo":"compréhension orale","pergunta":"Écoute. Quand faut-il prendre le comprimé ?","audio":"Prenez un comprimé matin et soir après le repas.","opcoes":["Matin et soir après le repas","Seulement le matin avant le repas","À midi pendant le repas"],"correta":0,"explicacao":"Il faut prendre un comprimé matin et soir, après le repas.","instrucao":"Ouça quantas vezes precisar e responda sobre o que foi dito."},{"tipo":"associations","pergunta":"Relie le symptôme à la partie du corps.","pares":[["mal à la gorge","garganta"],["mal au ventre","barriga"],["mal à la tête","cabeça"],["mal au dos","costas"]]},{"tipo":"traduction","pergunta":"Traduza: Sou alérgica a este medicamento.","respostas":["Je suis allergique à ce médicament"],"resposta":"Je suis allergique à ce médicament.","explicacao":"Allergique concorda com o gênero da pessoa: allergique é invariável na escrita."},{"tipo":"mission","pergunta":"Explique um problema de saúde numa farmácia.","instrucao":"Descreva sintomas e confirme como usar o produto.","modelo":"Bonjour, j'ai les yeux irrités depuis deux jours. Je ne prends aucun traitement. Ce produit convient-il ? Comment dois-je l'utiliser ?","checklist":["sintoma","duração","tratamento atual","modo de uso"]}]},{"id":"urgence_problemes","nivel":"Paris","tema":"urgence · vol · objets perdus","titulo":"En cas de problème","documentoTitulo":"Un portefeuille disparu","documento":"Dans un café, Diego remarque que son portefeuille a disparu. Il dit au serveur : « Excusez-moi, je pense qu'on m'a volé mon portefeuille. Est-ce que quelqu'un l'a rapporté ? » Le serveur répond que non et lui conseille de faire opposition à sa carte, puis de signaler le vol au commissariat. Diego demande l'adresse du poste de police le plus proche.","ferramentaTitulo":"j'ai perdu · on m'a volé · appeler les secours · commissariat","ferramenta":"Distinguez « j'ai perdu » d'« on m'a volé ». En France, le 112 est le numéro d'urgence européen, le 15 le SAMU, le 17 la police et le 18 les pompiers.","atividades":[{"tipo":"compréhension","pergunta":"Que doit faire Diego pour protéger son argent ?","opcoes":["Acheter un autre portefeuille","Faire opposition à sa carte","Retourner à l'hôtel"],"correta":1,"explicacao":"Faire opposition bloque rapidement la carte bancaire."},{"tipo":"lexique","pergunta":"Complète : Pour déclarer un vol, je vais au ___.","respostas":["commissariat"],"resposta":"commissariat","explicacao":"Le commissariat est le poste de police."},{"tipo":"grammaire","pergunta":"Transforme avec un pronom : Quelqu'un a volé mon téléphone.","respostas":["On m'a volé mon téléphone","Quelqu'un m'a volé mon téléphone"],"resposta":"On m'a volé mon téléphone.","explicacao":"Le pronom « me/m' » indique la personne victime du vol."},{"tipo":"médiation","pergunta":"Explique à un agent ce qui est arrivé à ton ami.","instrucao":"Indique objet, lieu, heure et description.","modelo":"Mon ami a perdu son sac vers 16 heures dans le métro à Châtelet. Il est noir avec une étiquette rouge et contient ses papiers.","checklist":["objet","lieu","heure","description"]},{"tipo":"interaction","pergunta":"Signale un objet perdu et demande la procédure.","instrucao":"Demande où déclarer la perte et quoi fournir.","modelo":"Bonjour, j'ai perdu mon passeport. Où dois-je déclarer la perte ? Quels documents ou informations dois-je fournir ?","checklist":["objet perdu","procédure","documents"]},{"tipo":"compréhension orale","pergunta":"Écoute. Quel numéro faut-il appeler ?","audio":"En cas d'urgence, appelez immédiatement le cent douze.","opcoes":["Le 15","Le 112","Le 18"],"correta":1,"explicacao":"Le 112 est le numéro européen d'urgence.","instrucao":"Ouça quantas vezes precisar e responda sobre o que foi dito."},{"tipo":"associations","pergunta":"Relie le numéro au service.","pares":[["15","SAMU"],["17","police"],["18","pompiers"],["112","urgence européenne"]]},{"tipo":"traduction","pergunta":"Traduza: Preciso de ajuda, minha bolsa foi roubada.","respostas":["J'ai besoin d'aide on m'a volé mon sac","J'ai besoin d'aide mon sac a été volé"],"resposta":"J'ai besoin d'aide, on m'a volé mon sac.","explicacao":"« On m'a volé » é uma forma natural de relatar furto."},{"tipo":"mission","pergunta":"Resolva uma emergência durante a viagem.","instrucao":"Peça ajuda, explique o problema e dê localização exata.","modelo":"Bonjour, j'ai besoin d'aide. Une personne est tombée et ne répond pas. Nous sommes devant le 20, boulevard Saint-Michel. Pouvez-vous envoyer les secours ?","checklist":["pedido de ajuda","problema","endereço","estado da pessoa"]}]},{"id":"parler_parisiens","nivel":"Paris","tema":"conversation · politesse · compréhension","titulo":"Parler avec les Parisiens","documentoTitulo":"Quand on parle trop vite","documento":"Dans une librairie, Ana demande un conseil. Le libraire répond rapidement et elle ne comprend pas tout. Ana dit : « Pardon, je suis en train d'apprendre le français. Vous pourriez parler un peu moins vite ? » Il reformule avec gentillesse. Ana vérifie : « Si j'ai bien compris, ce livre est plus facile et l'autre est plus complet, c'est ça ? » Le libraire confirme et poursuit la conversation.","ferramentaTitulo":"pardon · pourriez-vous répéter · si j'ai bien compris","ferramenta":"On peut demander de ralentir, de répéter ou de reformuler sans gêne. Commencez par bonjour, utilisez vous avec les inconnus et terminez par merci, bonne journée ou au revoir.","atividades":[{"tipo":"compréhension","pergunta":"Comment Ana vérifie-t-elle sa compréhension ?","opcoes":["Elle change de sujet","Elle reformule ce qu'elle a compris","Elle répond seulement oui"],"correta":1,"explicacao":"Elle résume l'information puis demande confirmation."},{"tipo":"lexique","pergunta":"Complète : Vous pourriez parler un peu moins ___ ?","respostas":["vite"],"resposta":"vite","explicacao":"« Moins vite » demande à la personne de ralentir."},{"tipo":"grammaire","pergunta":"Rends la demande plus polie : Répétez.","respostas":["Vous pourriez répéter s'il vous plaît","Pourriez-vous répéter s'il vous plaît"],"resposta":"Pourriez-vous répéter, s'il vous plaît ?","explicacao":"Le conditionnel rend la demande moins directe."},{"tipo":"médiation","pergunta":"Reformule une information complexe en français simple.","instrucao":"Commence par « Si j'ai bien compris ».","modelo":"Si j'ai bien compris, le magasin ferme plus tôt aujourd'hui et je dois revenir demain pour récupérer ma commande.","checklist":["formule de vérification","idée principale","phrase simple"]},{"tipo":"interaction","pergunta":"Maintiens une conversation quand tu ne comprends pas.","instrucao":"Demande de répéter, précise le mot difficile et confirme.","modelo":"Pardon, pourriez-vous répéter ? Je n'ai pas compris le mot après « réservation ». Vous voulez dire que je dois confirmer aujourd'hui, c'est ça ?","checklist":["demande de répétition","mot ciblé","confirmation"]},{"tipo":"écoute à trous","pergunta":"Écoute et complète : « Si j'ai bien compris, je dois revenir demain, ___ ? »","audio":"Si j'ai bien compris, je dois revenir demain, c'est ça ?","respostas":["c'est ça"],"resposta":"c'est ça","explicacao":"Estrutura útil para confirmar informações importantes.","instrucao":"Ouça e escreva somente as palavras que faltam."},{"tipo":"associations","pergunta":"Relie la formule à son intention.","pares":[["Pardon ?","signal de non-compréhension"],["Vous pouvez répéter ?","pedir repetição"],["Comment dit-on… ?","pedir uma palavra"],["C'est ça ?","pedir confirmação"]]},{"tipo":"traduction","pergunta":"Traduza: Desculpe, ainda não falo francês muito bem.","respostas":["Désolé je ne parle pas encore très bien français","Désolée je ne parle pas encore très bien français"],"resposta":"Désolé, je ne parle pas encore très bien français.","explicacao":"« Pas encore » significa ainda não."},{"tipo":"mission","pergunta":"Inicie e mantenha uma conversa curta em Paris.","instrucao":"Cumprimente, faça uma pergunta, peça esclarecimento e encerre com educação.","modelo":"Bonjour, vous connaissez un café calme dans le quartier ? Pardon, vous avez dit « au coin de la rue » ? D'accord, j'ai compris. Merci beaucoup et bonne journée !","checklist":["saudação","pergunta","esclarecimento","despedida"]}]}];
